export const STD_SOURCES: Readonly<Record<string, string>> = {
  "std/array.pengu": "realm array\n\nenchanting array<T>\n  is_empty = -> bool\n    #@ == 0\n\n  first = -> T?\n    if #@ == 0 then none else @[0]\n\n  last = -> T?\n    if #@ == 0 then none else @[#@ - 1]\n\n  index_of = (buscado: T) -> size_t?\n    mut i: size_t = 0\n    mut encontrado: size_t? = none\n    while i < #@\n      if @[i] == buscado\n        encontrado = i\n        break\n      i += 1\n    encontrado\n\n  contains = (buscado: T) -> bool\n    mut i: size_t = 0\n    mut esta = false\n    while i < #@\n      if @[i] == buscado\n        esta = true\n        break\n      i += 1\n    esta\n\n  to_vector = -> vector<T>\n    mut salida: vector<T> = []\n    mut i: size_t = 0\n    while i < #@\n      salida.push(@[i])\n      i += 1\n    salida\n\n  reversed = -> vector<T>\n    mut salida: vector<T> = []\n    mut i = #@\n    while i > 0\n      i -= 1\n      salida.push(@[i])\n    salida\n\n  slice = (inicio: size_t, largo: size_t) -> vector<T>\n    mut salida: vector<T> = []\n    mut i = inicio\n    while i < #@ and i < inicio + largo\n      salida.push(@[i])\n      i += 1\n    salida\n\n  join = (separador: string) -> string\n    mut salida = \"\"\n    mut i: size_t = 0\n    while i < #@\n      if i > 0\n        salida += separador\n      salida += \"#{@[i]}\"\n      i += 1\n    salida\n\n  min = -> T?\n    if #@ == 0\n      return none\n    mut candidato = @[0]\n    mut i: size_t = 1\n    while i < #@\n      if candidato > @[i]\n        candidato = @[i]\n      i += 1\n    candidato\n\n  max = -> T?\n    if #@ == 0\n      return none\n    mut candidato = @[0]\n    mut i: size_t = 1\n    while i < #@\n      if candidato < @[i]\n        candidato = @[i]\n      i += 1\n    candidato\n\n  find_if = (predicado: function<(T) -> bool>) -> T?\n    for valor in @\n      if predicado(valor)\n        return valor\n    none\n\n  any = (predicado: function<(T) -> bool>) -> bool\n    for valor in @\n      if predicado(valor)\n        return true\n    false\n\n  all = (predicado: function<(T) -> bool>) -> bool\n    for valor in @\n      if not predicado(valor)\n        return false\n    true\n\n  none = (predicado: function<(T) -> bool>) -> bool\n    for valor in @\n      if predicado(valor)\n        return false\n    true\n",
  "std/assert.d.pengu": "realm assert\n\ndeclare\n  that = (condition: bool) -> void\n  fail = (message: string) -> void\n",
  "std/char.pengu": "realm char\n\n-- Utilidades para `char`: clasificación y conversión de caja.\n-- Los métodos `to_upper`/`to_lower` son intrínsecos porque `int -> char`\n-- exige `unsafe` y aquí no queremos que el usuario lo pague.\n\ndeclare\n  to_upper_raw = (valor: char) -> char\n  to_lower_raw = (valor: char) -> char\n\nenchanting char\n  code = -> int\n    @ as int\n\n  is_digit = -> bool\n    @ >= '0' and @ <= '9'\n\n  is_alpha = -> bool\n    (@ >= 'a' and @ <= 'z') or (@ >= 'A' and @ <= 'Z')\n\n  is_alphanumeric = -> bool\n    @.is_digit() or @.is_alpha()\n\n  is_space = -> bool\n    @ == ' ' or @ == '\\t' or @ == '\\n' or @ == '\\r' or @ == '\\v' or @ == '\\f'\n\n  is_upper = -> bool\n    @ >= 'A' and @ <= 'Z'\n\n  is_lower = -> bool\n    @ >= 'a' and @ <= 'z'\n\n  is_ascii = -> bool\n    @.code() < 128\n\n  is_hex_digit = -> bool\n    @.is_digit() or (@ >= 'a' and @ <= 'f') or (@ >= 'A' and @ <= 'F')\n\n  is_control = -> bool\n    @.code() < 32 or @.code() == 127\n\n  is_punctuation = -> bool\n    @.is_ascii() and not @.is_alphanumeric() and not @.is_space() and not @.is_control()\n\n  digit_value = -> int\n    if @.is_digit() then @.code() - '0'.code() else 0\n\n  hex_value = -> int\n    if @.is_digit() then\n      @.code() - '0'.code()\n    else if @ >= 'a' and @ <= 'f' then\n      @.code() - 'a'.code() + 10\n    else if @ >= 'A' and @ <= 'F' then\n      @.code() - 'A'.code() + 10\n    else\n      -1\n\n  to_upper = -> char\n    to_upper_raw(@)\n\n  to_lower = -> char\n    to_lower_raw(@)\n",
  "std/color.pengu": "-- Color RGBA en coma flotante (0.0 a 1.0) con conversiones a bytes y hex.\n--\n-- Los componentes quedan sin recortar para poder sumar luz y hacer\n-- blending; `clamped()` devuelve una copia válida para pintar.\ninvoke \"std/double\"\ninvoke \"std/format\"\ninvoke \"std/int\"\ninvoke \"std/math\"\n\nrune Color\n  r: double\n  g: double\n  b: double\n  a: double\n\n  constructor(r: double, g: double, b: double, a: double)\n    @r = r\n    @g = g\n    @b = b\n    @a = a\n\nenchanting Color\n  clamped = -> Color\n    Color(math::clamp(@r, 0.0, 1.0), math::clamp(@g, 0.0, 1.0), math::clamp(@b, 0.0, 1.0), math::clamp(@a, 0.0, 1.0))\n\n  with_alpha = (alpha: double) -> Color\n    Color(@r, @g, @b, math::clamp(alpha, 0.0, 1.0))\n\n  is_opaque = -> bool\n    @a >= 1.0\n\n  is_transparent = -> bool\n    @a <= 0.0\n\n  luminance = -> double\n    @r * 0.2126 + @g * 0.7152 + @b * 0.0722\n\n  inverted = -> Color\n    Color(1.0 - @r, 1.0 - @g, 1.0 - @b, @a)\n\n  scale = (factor: double) -> Color\n    Color(@r * factor, @g * factor, @b * factor, @a)\n\n  lerp = (hacia: Color, t: double) -> Color\n    Color(@r + (hacia.r - @r) * t, @g + (hacia.g - @g) * t, @b + (hacia.b - @b) * t, @a + (hacia.a - @a) * t)\n\n  red8 = -> int\n    math::round(math::clamp(@r, 0.0, 1.0) * 255.0).to_int().value()\n\n  green8 = -> int\n    math::round(math::clamp(@g, 0.0, 1.0) * 255.0).to_int().value()\n\n  blue8 = -> int\n    math::round(math::clamp(@b, 0.0, 1.0) * 255.0).to_int().value()\n\n  alpha8 = -> int\n    math::round(math::clamp(@a, 0.0, 1.0) * 255.0).to_int().value()\n\n  channel_hex = (valor: int) -> string\n    format::pad_left_with(format::radix(valor, 16), size_t:: from (2), '0')\n\n  to_rgb8 = -> tuple<int, int, int>\n    (@red8(), @green8(), @blue8())\n\n  to_rgba8 = -> tuple<int, int, int, int>\n    (@red8(), @green8(), @blue8(), @alpha8())\n\n  to_hex = -> string\n    \"#\" + @channel_hex(@red8()) + @channel_hex(@green8()) + @channel_hex(@blue8())\n\n  to_hex_rgba = -> string\n    @to_hex() + @channel_hex(@alpha8())\n\n  to_hsv = -> tuple<double, double, double>\n    maximo = math::max(math::max(@r, @g), @b)\n    minimo = math::min(math::min(@r, @g), @b)\n    delta = maximo - minimo\n    mut tono = 0.0\n    if delta != 0.0\n      if maximo == @r\n        tono = 60.0 * math::fmod((@g - @b) / delta, 6.0)\n      if maximo == @g\n        tono = 60.0 * ((@b - @r) / delta + 2.0)\n      if maximo == @b\n        tono = 60.0 * ((@r - @g) / delta + 4.0)\n    if tono < 0.0\n      tono += 360.0\n    mut saturacion = 0.0\n    if maximo != 0.0\n      saturacion = delta / maximo\n    mut salida: tuple<double, double, double> = (tono, saturacion, maximo)\n    salida\n\n  operator == = (otro: ref<Color>) -> bool\n    @r == otro.r and @g == otro.g and @b == otro.b and @a == otro.a\n\n  to_string = -> string\n    \"Color(#{@r}, #{@g}, #{@b}, #{@a})\"\n\n    -- Constructores libres.\n\nrgb = (r: double, g: double, b: double) -> Color\n  Color(r, g, b, 1.0)\n\nrgba = (r: double, g: double, b: double, a: double) -> Color\n  Color(r, g, b, a)\n\nbyte_a_double = (valor: int) -> double\n  valor.clamp(0, 255).to_double() / 255.0\n\nfrom_rgb8 = (r: int, g: int, b: int) -> Color\n  Color(byte_a_double(r), byte_a_double(g), byte_a_double(b), 1.0)\n\nfrom_hex = (valor: int) -> Color\n  rojo = (valor >> 16) & 255\n  verde = (valor >> 8) & 255\n  azul = valor & 255\n  Color(byte_a_double(rojo), byte_a_double(verde), byte_a_double(azul), 1.0)\n\nfrom_hsv = (tono: double, saturacion: double, brillo: double) -> Color\n  mut h = math::fmod(tono, 360.0)\n  if h < 0.0\n    h += 360.0\n  s = math::clamp(saturacion, 0.0, 1.0)\n  v = math::clamp(brillo, 0.0, 1.0)\n  c = v * s\n  x = c * (1.0 - math::abs(math::fmod(h / 60.0, 2.0) - 1.0))\n  m = v - c\n  mut rojo = 0.0\n  mut verde = 0.0\n  mut azul = 0.0\n  if h < 60.0\n    rojo = c\n    verde = x\n  else if h < 120.0\n    rojo = x\n    verde = c\n  else if h < 180.0\n    verde = c\n    azul = x\n  else if h < 240.0\n    verde = x\n    azul = c\n  else if h < 300.0\n    rojo = x\n    azul = c\n  else\n    rojo = c\n    azul = x\n  Color(rojo + m, verde + m, azul + m, 1.0)\n\nwhite = -> Color\n  Color(1.0, 1.0, 1.0, 1.0)\n\nblack = -> Color\n  Color(0.0, 0.0, 0.0, 1.0)\n\ntransparent = -> Color\n  Color(0.0, 0.0, 0.0, 0.0)\n",
  "std/deque.pengu": "realm deque\n\nenchanting deque<T>\n  is_empty = -> bool\n    #@ == 0\n\n  first = -> T?\n    if #@ == 0 then none else @[0]\n\n  last = -> T?\n    if #@ == 0 then none else @[#@ - 1]\n\n  get_or = (indice: size_t, alternativa: T) -> T\n    if indice < #@ then @[indice] else alternativa\n\n  index_of = (buscado: T) -> size_t?\n    mut i: size_t = 0\n    mut encontrado: size_t? = none\n    while i < #@\n      if @[i] == buscado\n        encontrado = i\n        break\n      i += 1\n    encontrado\n\n  contains = (buscado: T) -> bool\n    @.index_of(buscado).is_some()\n\n  to_vector = -> vector<T>\n    mut salida: vector<T> = []\n    mut i: size_t = 0\n    while i < #@\n      salida.push(@[i])\n      i += 1\n    salida\n\n  join = (separador: string) -> string\n    mut salida = \"\"\n    mut i: size_t = 0\n    while i < #@\n      if i > 0\n        salida += separador\n      salida += \"#{@[i]}\"\n      i += 1\n    salida\n",
  "std/double.pengu": "realm double\n\ninvoke \"std/math\"\ninvoke \"std/format\"\n\nenchanting double\n  abs = -> double\n    if @ < 0.0 then -@ else @\n\n  min = (otro: double) -> double\n    if @ < otro then @ else otro\n\n  max = (otro: double) -> double\n    if @ > otro then @ else otro\n\n  clamp = (minimo: double, maximo: double) -> double\n    if @ < minimo then minimo else if @ > maximo then maximo else @\n\n  is_positive = -> bool\n    @ > 0.0\n\n  is_negative = -> bool\n    @ < 0.0\n\n  is_zero = -> bool\n    @ == 0.0\n\n  between = (minimo: double, maximo: double) -> bool\n    @ >= minimo and @ <= maximo\n\n    -- Raíces, exponenciales y logaritmos.\n  sqrt = -> double\n    math::sqrt(@)\n\n  cbrt = -> double\n    math::cbrt(@)\n\n  pow = (exponente: double) -> double\n    math::pow(@, exponente)\n\n  exp = -> double\n    math::exp(@)\n\n  ln = -> double\n    math::ln(@)\n\n  log2 = -> double\n    math::log2(@)\n\n  log10 = -> double\n    math::log10(@)\n\n    -- Redondeos.\n  floor = -> double\n    math::floor(@)\n\n  ceil = -> double\n    math::ceil(@)\n\n  round = -> double\n    math::round(@)\n\n  trunc = -> double\n    math::trunc(@)\n\n  fract = -> double\n    @ - math::floor(@)\n\n  round_to = (decimales: int) -> double\n    factor = math::pow(10.0, decimales as double)\n    math::round(@ * factor) / factor\n\n    -- Geometría y comparaciones.\n  hypot = (otro: double) -> double\n    math::hypot(@, otro)\n\n  is_finite = -> bool\n    math::is_finite(@)\n\n  is_infinite = -> bool\n    math::is_infinite(@)\n\n  is_nan = -> bool\n    math::is_nan(@)\n\n  is_sign_negative = -> bool\n    math::signbit(@)\n\n  signum = -> double\n    if @ > 0.0 then 1.0 else if @ < 0.0 then -1.0 else 0.0\n\n  lerp = (hacia: double, t: double) -> double\n    @ + (hacia - @) * t\n\n  approx_eq = (otro: double, epsilon: double = 1e-9) -> bool\n    math::abs(@ - otro) <= epsilon\n\n    -- Ángulos.\n  to_radians = -> double\n    math::deg_to_rad(@)\n\n  to_degrees = -> double\n    math::rad_to_deg(@)\n\n    -- Texto con precisión controlada.\n  to_fixed = (decimales: int) -> string\n    format::fixed(@, decimales)\n\n  to_scientific = (decimales: int) -> string\n    format::scientific(@, decimales)\n\n    -- Conversiones. Las que pierden información piden `try_from` explícito.\n  to_int = -> int?\n    int::try_from(@)\n\n  to_float = -> float?\n    float::try_from(@)\n\n  to_long_double = -> long double\n    @ as long double\n",
  "std/easing.pengu": "-- Curvas de interpolación para animaciones.\n--\n-- Todas reciben un `t` normalizado (0.0 a 1.0) y devuelven un valor\n-- normalizado; no recortan `t` para permitir rebotes y elasticidad.\ninvoke \"std/int\"\ninvoke \"std/math\"\n\nlinear = (t: double) -> double\n  t\n\nclamp_unit = (t: double) -> double\n  if t < 0.0\n    return 0.0\n  if t > 1.0\n    return 1.0\n  t\n\nping_pong = (t: double) -> double\n  mut ciclo = math::fmod(t, 2.0)\n  if ciclo < 0.0\n    ciclo += 2.0\n  if ciclo <= 1.0\n    return ciclo\n  2.0 - ciclo\n\nsteps = (t: double, pasos: int) -> double\n  if pasos <= 1\n    return 0.0\n  math::floor(clamp_unit(t) * pasos.to_double()) / (pasos - 1).to_double()\n\nsmoothstep = (borde0: double, borde1: double, x: double) -> double\n  if borde1 == borde0\n    return 0.0\n  t = clamp_unit((x - borde0) / (borde1 - borde0))\n  t * t * (3.0 - 2.0 * t)\n\nsmootherstep = (borde0: double, borde1: double, x: double) -> double\n  if borde1 == borde0\n    return 0.0\n  t = clamp_unit((x - borde0) / (borde1 - borde0))\n  t * t * t * (t * (t * 6.0 - 15.0) + 10.0)\n\nquadratic_in = (t: double) -> double\n  t * t\n\nquadratic_out = (t: double) -> double\n  1.0 - (1.0 - t) * (1.0 - t)\n\nquadratic_in_out = (t: double) -> double\n  if t < 0.5\n    return 2.0 * t * t\n  1.0 - 2.0 * (1.0 - t) * (1.0 - t)\n\ncubic_in = (t: double) -> double\n  t * t * t\n\ncubic_out = (t: double) -> double\n  u = 1.0 - t\n  1.0 - u * u * u\n\ncubic_in_out = (t: double) -> double\n  if t < 0.5\n    return 4.0 * t * t * t\n  u = 1.0 - t\n  1.0 - 4.0 * u * u * u\n\nquartic_in = (t: double) -> double\n  t * t * t * t\n\nquartic_out = (t: double) -> double\n  u = 1.0 - t\n  1.0 - u * u * u * u\n\nquartic_in_out = (t: double) -> double\n  if t < 0.5\n    return 8.0 * t * t * t * t\n  u = 1.0 - t\n  1.0 - 8.0 * u * u * u * u\n\nquintic_in = (t: double) -> double\n  t * t * t * t * t\n\nquintic_out = (t: double) -> double\n  u = 1.0 - t\n  1.0 - u * u * u * u * u\n\nsine_in = (t: double) -> double\n  1.0 - math::cos(t * math::pi / 2.0)\n\nsine_out = (t: double) -> double\n  math::sin(t * math::pi / 2.0)\n\nsine_in_out = (t: double) -> double\n  0.5 * (1.0 - math::cos(t * math::pi))\n\nexponential_in = (t: double) -> double\n  if t == 0.0\n    return 0.0\n  math::pow(2.0, 10.0 * (t - 1.0))\n\nexponential_out = (t: double) -> double\n  if t == 1.0\n    return 1.0\n  1.0 - math::pow(2.0, -10.0 * t)\n\nexponential_in_out = (t: double) -> double\n  if t == 0.0\n    return 0.0\n  if t == 1.0\n    return 1.0\n  if t < 0.5\n    return 0.5 * math::pow(2.0, 20.0 * t - 10.0)\n  1.0 - 0.5 * math::pow(2.0, -20.0 * t + 10.0)\n\ncircular_in = (t: double) -> double\n  1.0 - math::sqrt(1.0 - t * t)\n\ncircular_out = (t: double) -> double\n  math::sqrt(1.0 - (t - 1.0) * (t - 1.0))\n\ncircular_in_out = (t: double) -> double\n  if t < 0.5\n    return 0.5 * (1.0 - math::sqrt(1.0 - 4.0 * t * t))\n  0.5 * (math::sqrt(1.0 - (-2.0 * t + 2.0) * (-2.0 * t + 2.0)) + 1.0)\n\nback_in = (t: double) -> double\n  c = 1.70158\n  t * t * ((c + 1.0) * t - c)\n\nback_out = (t: double) -> double\n  c = 1.70158\n  u = t - 1.0\n  u * u * ((c + 1.0) * u + c) + 1.0\n\nback_in_out = (t: double) -> double\n  c = 1.70158 * 1.525\n  if t < 0.5\n    u = 2.0 * t\n    return 0.5 * (u * u * ((c + 1.0) * u - c))\n  u = 2.0 * t - 2.0\n  0.5 * (u * u * ((c + 1.0) * u + c) + 2.0)\n\nbounce_out = (t: double) -> double\n  if t < 1.0 / 2.75\n    return 7.5625 * t * t\n  if t < 2.0 / 2.75\n    u = t - 1.5 / 2.75\n    return 7.5625 * u * u + 0.75\n  if t < 2.5 / 2.75\n    u = t - 2.25 / 2.75\n    return 7.5625 * u * u + 0.9375\n  u = t - 2.625 / 2.75\n  7.5625 * u * u + 0.984375\n\nbounce_in = (t: double) -> double\n  1.0 - bounce_out(1.0 - t)\n\nbounce_in_out = (t: double) -> double\n  if t < 0.5\n    return 0.5 * bounce_in(t * 2.0)\n  0.5 * bounce_out(t * 2.0 - 1.0) + 0.5\n\nelastic_out = (t: double) -> double\n  if t == 0.0\n    return 0.0\n  if t == 1.0\n    return 1.0\n  c = 2.0 * math::pi / 3.0\n  math::pow(2.0, -10.0 * t) * math::sin((t * 10.0 - 0.75) * c) + 1.0\n\nelastic_in = (t: double) -> double\n  if t == 0.0\n    return 0.0\n  if t == 1.0\n    return 1.0\n  c = 2.0 * math::pi / 3.0\n  -math::pow(2.0, 10.0 * t - 10.0) * math::sin((t * 10.0 - 10.75) * c)\n\nelastic_in_out = (t: double) -> double\n  if t == 0.0\n    return 0.0\n  if t == 1.0\n    return 1.0\n  c = 2.0 * math::pi / 4.5\n  if t < 0.5\n    return -0.5 * math::pow(2.0, 20.0 * t - 10.0) * math::sin((20.0 * t - 11.125) * c)\n  0.5 * math::pow(2.0, -20.0 * t + 10.0) * math::sin((20.0 * t - 11.125) * c) + 1.0\n",
  "std/float.pengu": "realm float\n\ninvoke \"std/math\"\n\n-- Primitivas específicas de «float»: las de <cmath> tienen una sobrecarga\n-- por ancho, así que el resultado conserva el tipo.\ndeclare\n  sqrt = (x: float) -> float\n  cbrt = (x: float) -> float\n  pow = (base: float, exponent: float) -> float\n  exp = (x: float) -> float\n  ln = (x: float) -> float\n  log2 = (x: float) -> float\n  log10 = (x: float) -> float\n  floor = (x: float) -> float\n  ceil = (x: float) -> float\n  round = (x: float) -> float\n  trunc = (x: float) -> float\n  hypot = (x: float, y: float) -> float\n  is_finite = (x: float) -> bool\n  is_infinite = (x: float) -> bool\n  is_nan = (x: float) -> bool\n  is_sign_negative = (x: float) -> bool\n  to_fixed = (x: float, decimals: int) -> string\n  to_scientific = (x: float, decimals: int) -> string\n\nenchanting float\n  abs = -> float\n    if @ < 0.0 then -@ else @\n\n  min = (otro: float) -> float\n    if @ < otro then @ else otro\n\n  max = (otro: float) -> float\n    if @ > otro then @ else otro\n\n  clamp = (minimo: float, maximo: float) -> float\n    if @ < minimo then minimo else if @ > maximo then maximo else @\n\n  is_positive = -> bool\n    @ > 0.0\n\n  is_negative = -> bool\n    @ < 0.0\n\n  is_zero = -> bool\n    @ == 0.0\n\n  between = (minimo: float, maximo: float) -> bool\n    @ >= minimo and @ <= maximo\n\n  sqrt = -> float\n    sqrt(@)\n\n  cbrt = -> float\n    cbrt(@)\n\n  pow = (exponente: float) -> float\n    pow(@, exponente)\n\n  exp = -> float\n    exp(@)\n\n  ln = -> float\n    ln(@)\n\n  log2 = -> float\n    log2(@)\n\n  log10 = -> float\n    log10(@)\n\n  floor = -> float\n    floor(@)\n\n  ceil = -> float\n    ceil(@)\n\n  round = -> float\n    round(@)\n\n  trunc = -> float\n    trunc(@)\n\n  fract = -> float\n    @ - floor(@)\n\n  round_to = (decimales: int) -> float\n    factor = pow(10 as float, decimales as float)\n    round(@ * factor) / factor\n\n  hypot = (otro: float) -> float\n    hypot(@, otro)\n\n  is_finite = -> bool\n    is_finite(@)\n\n  is_infinite = -> bool\n    is_infinite(@)\n\n  is_nan = -> bool\n    is_nan(@)\n\n  is_sign_negative = -> bool\n    is_sign_negative(@)\n\n  signum = -> float\n    if @ > 0.0 then float:: from (1.0) else if @ < 0.0 then float:: from (-1.0) else float:: from (0.0)\n\n  lerp = (hacia: float, t: float) -> float\n    @ + (hacia - @) * t\n\n  approx_eq = (otro: float, epsilon: float) -> bool\n    (@ - otro).abs() <= epsilon\n\n  to_fixed = (decimales: int) -> string\n    to_fixed(@, decimales)\n\n  to_scientific = (decimales: int) -> string\n    to_scientific(@, decimales)\n\n  to_double = -> double\n    @ as double\n\n  to_int = -> int?\n    int::try_from(@)\n",
  "std/format.pengu": "realm format\n\ninvoke \"std/string\"\ninvoke \"std/vector\"\n\ndeclare\n  format_values = (partes: vector<any>) -> string\n  fixed = (valor: double, decimales: int) -> string\n  scientific = (valor: double, decimales: int) -> string\n  radix = (valor: int, base: int) -> string\n  template_values = (texto: ref<string>, partes: vector<any>) -> string\n\nformat = (...partes: any) -> string\n  format_values(partes)\n\n  -- Números en otras bases (sin signo de prefijo, como `format::radix`).\nhex = (valor: int) -> string\n  radix(valor, 16)\n\nbin = (valor: int) -> string\n  radix(valor, 2)\n\noct = (valor: int) -> string\n  radix(valor, 8)\n\npad_left = (texto: string, ancho: size_t) -> string\n  texto.pad_start(ancho)\n\npad_left_with = (texto: string, ancho: size_t, relleno: char) -> string\n  texto.pad_start_with(ancho, relleno)\n\npad_right = (texto: string, ancho: size_t) -> string\n  texto.pad_end(ancho)\n\npad_right_with = (texto: string, ancho: size_t, relleno: char) -> string\n  texto.pad_end_with(ancho, relleno)\n\ncenter = (texto: string, ancho: size_t) -> string\n  texto.pad_center(ancho)\n\ncenter_with = (texto: string, ancho: size_t, relleno: char) -> string\n  texto.pad_center_with(ancho, relleno)\n\njoin = (partes: ref<vector<string>>, separador: string) -> string\n  mut salida = \"\"\n  mut primero = true\n  for parte in partes\n    if primero\n      primero = false\n    else\n      salida += separador\n    salida += parte\n  salida\n\n  -- Agrupa los miles: 1234567 -> \"1.234.567\" (el separador lo elige quien llama).\nseparated = (valor: int, separador: string) -> string\n  mut negativo = valor < 0\n  mut digitos = \"#{valor}\"\n  if negativo\n    digitos = digitos.substr(1, #digitos - 1)\n  mut salida = \"\"\n  mut cuenta: int = 0\n  mut i: size_t = #digitos\n  while i > 0\n    i -= 1\n    salida = \"#{digitos[i]}#{salida}\"\n    cuenta += 1\n    if cuenta % 3 == 0 and i > 0\n      salida = \"#{separador}#{salida}\"\n  if negativo\n    \"-\" + salida\n  else\n    salida\n\n    -- Plantilla con «{}»: sustituye cada hueco por el siguiente valor.\ntemplate = (texto: string, ...partes: any) -> string\n  template_values(ref(texto), partes)\n",
  "std/fs.pengu": "realm fs\n\ninvoke \"std/string\"\ninvoke \"std/vector\"\n\n-- Intrínsecos: todo lo que toca el sistema de archivos de verdad.\ndeclare\n  read_to_string = (ruta: string) -> string?\n  read_bytes = (ruta: string) -> vector<uint8_t>?\n  write_string = (ruta: string, contenido: string) -> bool\n  write_bytes = (ruta: string, bytes: ref<vector<uint8_t>>) -> bool\n  append_string = (ruta: string, contenido: string) -> bool\n  exists = (ruta: string) -> bool\n  is_file = (ruta: string) -> bool\n  is_dir = (ruta: string) -> bool\n  remove = (ruta: string) -> bool\n  create_dir = (ruta: string) -> bool\n  list_dir = (ruta: string) -> vector<string>\n  file_size = (ruta: string) -> int?\n  rename = (desde: string, hasta: string) -> bool\n  copy = (desde: string, hasta: string) -> bool\n  canonicalize = (ruta: string) -> string?\n\n  -- Lee líneas sin el salto final: «a\\nb\\n» → [\"a\", \"b\"].\nread_lines = (ruta: string) -> vector<string>?\n  texto = read_to_string(ruta)\n  if texto.is_none()\n    return none\n  mut lineas = texto.value().split_lines()\n  if not lineas.is_empty() and lineas.last() == \"\"\n    lineas.pop()\n  lineas\n\nwrite_lines = (ruta: string, lineas: ref<vector<string>>) -> bool\n  mut texto = \"\"\n  for linea in lineas\n    texto += \"#{linea}\\n\"\n  write_string(ruta, texto)\n\nappend_line = (ruta: string, linea: string) -> bool\n  append_string(ruta, \"#{linea}\\n\")\n\nread_or = (ruta: string, respaldo: string) -> string\n  texto = read_to_string(ruta)\n  if texto.is_some() then texto.value() else respaldo\n\n  -- Escribe solo si el archivo no existe todavía.\nwrite_new = (ruta: string, contenido: string) -> bool\n  if exists(ruta) then false else write_string(ruta, contenido)\n\nremove_if_exists = (ruta: string) -> bool\n  if exists(ruta) then remove(ruta) else true\n\nensure_dir = (ruta: string) -> bool\n  if exists(ruta) then is_dir(ruta) else create_dir(ruta)\n",
  "std/geometry.pengu": "-- Geometría para juegos: vectores, rectángulos y transformaciones.\n--\n-- Los runes no tienen métodos estáticos, así que los constructores con\n-- nombre propio son funciones libres (`geometry::zero_vec2()`). El tipo\n-- se nombra cualificado desde otros módulos (`geometry::Vec2`).\ninvoke \"std/io\"\ninvoke \"std/math\"\ninvoke \"std/ordering\"\n\nrune Vec2\n  x: double\n  y: double\n\n  constructor(x: double, y: double)\n    @x = x\n    @y = y\n\nenchanting Vec2\n  length_squared = -> double\n    @x * @x + @y * @y\n\n  length = -> double\n    math::sqrt(@length_squared())\n\n  dot = (otro: Vec2) -> double\n    @x * otro.x + @y * otro.y\n\n  cross = (otro: Vec2) -> double\n    @x * otro.y - @y * otro.x\n\n  normalized = -> Vec2\n    tamano = @length()\n    if tamano == 0.0\n      return Vec2(0.0, 0.0)\n    Vec2(@x / tamano, @y / tamano)\n\n  distance_to = (otro: Vec2) -> double\n    (Vec2(@x - otro.x, @y - otro.y)).length()\n\n  direction_to = (otro: Vec2) -> Vec2\n    Vec2(otro.x - @x, otro.y - @y).normalized()\n\n  lerp = (hacia: Vec2, t: double) -> Vec2\n    Vec2(@x + (hacia.x - @x) * t, @y + (hacia.y - @y) * t)\n\n  angle = -> double\n    math::atan2(@y, @x)\n\n  rotated = (radianes: double) -> Vec2\n    coseno = math::cos(radianes)\n    seno = math::sin(radianes)\n    Vec2(@x * coseno - @y * seno, @x * seno + @y * coseno)\n\n  perpendicular = -> Vec2\n    Vec2(-@y, @x)\n\n  abs = -> Vec2\n    Vec2(math::abs(@x), math::abs(@y))\n\n  clamp_length = (maximo: double) -> Vec2\n    if @length_squared() <= maximo * maximo\n      return Vec2(@x, @y)\n    @normalized() * maximo\n\n  is_zero = -> bool\n    @x == 0.0 and @y == 0.0\n\n  equals = (otro: Vec2, epsilon: double = 1e-9) -> bool\n    math::abs(@x - otro.x) <= epsilon and math::abs(@y - otro.y) <= epsilon\n\n  mut add = (otro: ref<Vec2>) -> void\n    @x += otro.x\n    @y += otro.y\n\n  mut scale = (factor: double) -> void\n    @x *= factor\n    @y *= factor\n\n  mut move_towards = (objetivo: Vec2, paso: double) -> void\n    distancia = @distance_to(objetivo)\n    if distancia <= paso or distancia == 0.0\n      @x = objetivo.x\n      @y = objetivo.y\n    else\n      direccion = @direction_to(objetivo)\n      @x += direccion.x * paso\n      @y += direccion.y * paso\n\n  operator + = (otro: ref<Vec2>) -> Vec2\n    Vec2(@x + otro.x, @y + otro.y)\n\n  operator - = (otro: ref<Vec2>) -> Vec2\n    Vec2(@x - otro.x, @y - otro.y)\n\n  operator * = (escala: double) -> Vec2\n    Vec2(@x * escala, @y * escala)\n\n  operator / = (escala: double) -> Vec2\n    Vec2(@x / escala, @y / escala)\n\n  operator == = (otro: ref<Vec2>) -> bool\n    @x == otro.x and @y == otro.y\n\n  operator <=> = (otro: ref<Vec2>) -> Ordering\n    if @x != otro.x\n      return @x <=> otro.x\n    @y <=> otro.y\n\n  to_string = -> string\n    \"(#{@x}, #{@y})\"\n\nrune Vec3\n  x: double\n  y: double\n  z: double\n\n  constructor(x: double, y: double, z: double)\n    @x = x\n    @y = y\n    @z = z\n\nenchanting Vec3\n  length_squared = -> double\n    @x * @x + @y * @y + @z * @z\n\n  length = -> double\n    math::sqrt(@length_squared())\n\n  dot = (otro: Vec3) -> double\n    @x * otro.x + @y * otro.y + @z * otro.z\n\n  cross = (otro: Vec3) -> Vec3\n    Vec3(@y * otro.z - @z * otro.y, @z * otro.x - @x * otro.z, @x * otro.y - @y * otro.x)\n\n  normalized = -> Vec3\n    tamano = @length()\n    if tamano == 0.0\n      return Vec3(0.0, 0.0, 0.0)\n    Vec3(@x / tamano, @y / tamano, @z / tamano)\n\n  distance_to = (otro: Vec3) -> double\n    Vec3(@x - otro.x, @y - otro.y, @z - otro.z).length()\n\n  lerp = (hacia: Vec3, t: double) -> Vec3\n    Vec3(@x + (hacia.x - @x) * t, @y + (hacia.y - @y) * t, @z + (hacia.z - @z) * t)\n\n  is_zero = -> bool\n    @x == 0.0 and @y == 0.0 and @z == 0.0\n\n  operator + = (otro: Vec3) -> Vec3\n    Vec3(@x + otro.x, @y + otro.y, @z + otro.z)\n\n  operator - = (otro: Vec3) -> Vec3\n    Vec3(@x - otro.x, @y - otro.y, @z - otro.z)\n\n  operator * = (escala: double) -> Vec3\n    Vec3(@x * escala, @y * escala, @z * escala)\n\n  operator == = (otro: Vec3) -> bool\n    @x == otro.x and @y == otro.y and @z == otro.z\n\n  to_string = -> string\n    \"(#{@x}, #{@y}, #{@z})\"\n\nrune Rect\n  x: double\n  y: double\n  width: double\n  height: double\n\n  constructor(x: double, y: double, width: double, height: double)\n    @x = x\n    @y = y\n    @width = width\n    @height = height\n\nenchanting Rect\n  right = -> double\n    @x + @width\n\n  bottom = -> double\n    @y + @height\n\n  center = -> Vec2\n    Vec2(@x + @width / 2.0, @y + @height / 2.0)\n\n  area = -> double\n    @width * @height\n\n  is_empty = -> bool\n    @width <= 0.0 or @height <= 0.0\n\n  contains = (punto: Vec2) -> bool\n    punto.x >= @x and punto.x <= @right() and punto.y >= @y and punto.y <= @bottom()\n\n  contains_rect = (otro: Rect) -> bool\n    otro.x >= @x and otro.y >= @y and otro.right() <= @right() and otro.bottom() <= @bottom()\n\n  intersects = (otro: Rect) -> bool\n    @x < otro.right() and otro.x < @right() and @y < otro.bottom() and otro.y < @bottom()\n\n  intersection = (otro: Rect) -> Rect?\n    izquierda = math::max(@x, otro.x)\n    arriba = math::max(@y, otro.y)\n    derecha = math::min(@right(), otro.right())\n    abajo = math::min(@bottom(), otro.bottom())\n    if derecha <= izquierda or abajo <= arriba\n      return none\n    Rect(izquierda, arriba, derecha - izquierda, abajo - arriba)\n\n  union = (otro: Rect) -> Rect\n    izquierda = math::min(@x, otro.x)\n    arriba = math::min(@y, otro.y)\n    derecha = math::max(@right(), otro.right())\n    abajo = math::max(@bottom(), otro.bottom())\n    Rect(izquierda, arriba, derecha - izquierda, abajo - arriba)\n\n  expanded = (margen: double) -> Rect\n    Rect(@x - margen, @y - margen, @width + margen * 2.0, @height + margen * 2.0)\n\n  translated = (dx: double, dy: double) -> Rect\n    Rect(@x + dx, @y + dy, @width, @height)\n\n  overlaps = (punto: Vec2) -> bool\n    @contains(punto)\n\n  to_string = -> string\n    \"Rect(#{@x}, #{@y}, #{@width}, #{@height})\"\n\nrune Transform2D\n  position: Vec2\n  rotation: double\n  scale: Vec2\n\n  constructor(position: Vec2, rotation: double, scale: Vec2)\n    @position = position\n    @rotation = rotation\n    @scale = scale\n\nenchanting Transform2D\n  apply = (punto: Vec2) -> Vec2\n    escalado = Vec2(punto.x * @scale.x, punto.y * @scale.y)\n    rotado = escalado.rotated(@rotation)\n    rotado + @position\n\n  apply_direction = (direccion: Vec2) -> Vec2\n    Vec2(direccion.x * @scale.x, direccion.y * @scale.y).rotated(@rotation)\n\n  inverse_apply = (punto: Vec2) -> Vec2\n    relativo = Vec2(punto.x - @position.x, punto.y - @position.y)\n    desrotado = relativo.rotated(-@rotation)\n    Vec2(desrotado.x / @scale.x, desrotado.y / @scale.y)\n\n  to_string = -> string\n    \"Transform2D(#{@position}, #{@rotation}, #{@scale})\"\n\n    -- Constructores libres (los runes no admiten métodos estáticos).\n\nvec2 = (x: double, y: double) -> Vec2\n  Vec2(x, y)\n\nzero_vec2 = -> Vec2\n  Vec2(0.0, 0.0)\n\nunit_vec2 = (x: double, y: double) -> Vec2\n  Vec2(x, y).normalized()\n\nvec3 = (x: double, y: double, z: double) -> Vec3\n  Vec3(x, y, z)\n\nzero_vec3 = -> Vec3\n  Vec3(0.0, 0.0, 0.0)\n\nrect = (x: double, y: double, width: double, height: double) -> Rect\n  Rect(x, y, width, height)\n\nrect_from_center = (centro: Vec2, width: double, height: double) -> Rect\n  Rect(centro.x - width / 2.0, centro.y - height / 2.0, width, height)\n\ntransform_identity = -> Transform2D\n  Transform2D(Vec2(0.0, 0.0), 0.0, Vec2(1.0, 1.0))\n\ntransform_at = (posicion: Vec2) -> Transform2D\n  Transform2D(Vec2(posicion.x, posicion.y), 0.0, Vec2(1.0, 1.0))\n",
  "std/int.pengu": "realm int\n\ninvoke \"std/math\"\ninvoke \"std/format\"\n\nenchanting int\n  abs = -> int\n    if @ < 0 then -@ else @\n\n  min = (otro: int) -> int\n    if @ < otro then @ else otro\n\n  max = (otro: int) -> int\n    if @ > otro then @ else otro\n\n  clamp = (minimo: int, maximo: int) -> int\n    if @ < minimo then minimo else if @ > maximo then maximo else @\n\n  is_even = -> bool\n    @ % 2 == 0\n\n  is_odd = -> bool\n    @ % 2 != 0\n\n  sign = -> int\n    if @ > 0 then 1 else if @ < 0 then -1 else 0\n\n  is_positive = -> bool\n    @ > 0\n\n  is_negative = -> bool\n    @ < 0\n\n  is_zero = -> bool\n    @ == 0\n\n  between = (minimo: int, maximo: int) -> bool\n    @ >= minimo and @ <= maximo\n\n    -- División y resto que redondean hacia abajo: con los operadores\n    -- `-7 / 2` da `-3` y `-7 % 2` da `-1`; aquí dan `-4` y `1`.\n  div_floor = (otro: int) -> int\n    cociente = @ / otro\n    resto = @ % otro\n    if resto != 0 and (resto < 0) != (otro < 0) then cociente - 1 else cociente\n\n  div_ceil = (otro: int) -> int\n    cociente = @ / otro\n    resto = @ % otro\n    if resto != 0 and (resto < 0) == (otro < 0) then cociente + 1 else cociente\n\n  mod_floor = (otro: int) -> int\n    resto = @ % otro\n    if resto != 0 and (resto < 0) != (otro < 0) then resto + otro else resto\n\n    -- Resto siempre no negativo: el que usan los índices circulares.\n  mod_euclid = (otro: int) -> int\n    resto = @ % otro\n    if resto < 0 then resto + otro.abs() else resto\n\n  pow = (exponente: int) -> int\n    math::ipow(@, exponente)\n\n    -- Encaje circular en [minimo, maximo).\n  wrap = (minimo: int, maximo: int) -> int\n    minimo + (@ - minimo).mod_euclid(maximo - minimo)\n\n  next_multiple_of = (paso: int) -> int\n    if paso == 0 then @ else (@ + paso - 1).div_floor(paso) * paso\n\n  abs_diff = (otro: int) -> int\n    diferencia = @ - otro\n    if diferencia < 0 then -diferencia else diferencia\n\n  digits = -> size_t\n    mut n = @ as int64_t\n    if n < 0\n      n = -n\n    mut cuenta = 1\n    while n >= 10\n      n /= 10\n      cuenta += 1\n    size_t:: from (cuenta)\n\n  is_power_of_two = -> bool\n    @ > 0 and (@ & (@ - 1)) == 0\n\n  to_double = -> double\n    @ as double\n\n  to_float = -> float\n    @ as float\n\n  to_int64 = -> int64_t\n    @ as int64_t\n\n  to_size = -> size_t\n    size_t:: from (@)\n\n  to_radix = (base: int) -> string\n    format::radix(@, base)\n",
  "std/integers.pengu": "realm integers\n\n-- Enteros de ancho fijo. Archivo generado por scripts/gen_integers.ts:\n-- no lo edites a mano, cambia la tabla del generador y vuelve a ejecutarlo.\n\ndeclare\n  int8_max = () -> int8_t\n  int8_min = () -> int8_t\n  int16_max = () -> int16_t\n  int16_min = () -> int16_t\n  int32_max = () -> int32_t\n  int32_min = () -> int32_t\n  int64_max = () -> int64_t\n  int64_min = () -> int64_t\n  uint8_max = () -> uint8_t\n  uint8_min = () -> uint8_t\n  uint16_max = () -> uint16_t\n  uint16_min = () -> uint16_t\n  uint32_max = () -> uint32_t\n  uint32_min = () -> uint32_t\n  uint64_max = () -> uint64_t\n  uint64_min = () -> uint64_t\n\nenchanting int8_t\n  abs = -> int8_t\n    if @ < 0 then -@ else @\n\n  min = (otro: int8_t) -> int8_t\n    if @ < otro then @ else otro\n\n  max = (otro: int8_t) -> int8_t\n    if @ > otro then @ else otro\n\n  clamp = (minimo: int8_t, maximo: int8_t) -> int8_t\n    if @ < minimo then minimo else if @ > maximo then maximo else @\n\n  sign = -> int\n    if @ > 0 then 1 else if @ < 0 then -1 else 0\n\n  is_even = -> bool\n    (@ & 1) == 0\n\n  is_odd = -> bool\n    (@ & 1) != 0\n\n  is_positive = -> bool\n    @ > 0\n\n  is_negative = -> bool\n    @ < 0\n\n  is_zero = -> bool\n    @ == 0\n\n  min_value = -> int8_t\n    int8_min()\n\n  max_value = -> int8_t\n    int8_max()\n\n  to_int = -> int?\n    int::try_from(@)\n\n  to_int64 = -> int64_t?\n    int64_t::try_from(@)\n\n  to_uint64 = -> uint64_t?\n    uint64_t::try_from(@)\n\n  to_double = -> double\n    @ as double\n\n  to_size = -> size_t?\n    size_t::try_from(@)\n\nenchanting int16_t\n  abs = -> int16_t\n    if @ < 0 then -@ else @\n\n  min = (otro: int16_t) -> int16_t\n    if @ < otro then @ else otro\n\n  max = (otro: int16_t) -> int16_t\n    if @ > otro then @ else otro\n\n  clamp = (minimo: int16_t, maximo: int16_t) -> int16_t\n    if @ < minimo then minimo else if @ > maximo then maximo else @\n\n  sign = -> int\n    if @ > 0 then 1 else if @ < 0 then -1 else 0\n\n  is_even = -> bool\n    (@ & 1) == 0\n\n  is_odd = -> bool\n    (@ & 1) != 0\n\n  is_positive = -> bool\n    @ > 0\n\n  is_negative = -> bool\n    @ < 0\n\n  is_zero = -> bool\n    @ == 0\n\n  min_value = -> int16_t\n    int16_min()\n\n  max_value = -> int16_t\n    int16_max()\n\n  to_int = -> int?\n    int::try_from(@)\n\n  to_int64 = -> int64_t?\n    int64_t::try_from(@)\n\n  to_uint64 = -> uint64_t?\n    uint64_t::try_from(@)\n\n  to_double = -> double\n    @ as double\n\n  to_size = -> size_t?\n    size_t::try_from(@)\n\nenchanting int32_t\n  abs = -> int32_t\n    if @ < 0 then -@ else @\n\n  min = (otro: int32_t) -> int32_t\n    if @ < otro then @ else otro\n\n  max = (otro: int32_t) -> int32_t\n    if @ > otro then @ else otro\n\n  clamp = (minimo: int32_t, maximo: int32_t) -> int32_t\n    if @ < minimo then minimo else if @ > maximo then maximo else @\n\n  sign = -> int\n    if @ > 0 then 1 else if @ < 0 then -1 else 0\n\n  is_even = -> bool\n    (@ & 1) == 0\n\n  is_odd = -> bool\n    (@ & 1) != 0\n\n  is_positive = -> bool\n    @ > 0\n\n  is_negative = -> bool\n    @ < 0\n\n  is_zero = -> bool\n    @ == 0\n\n  min_value = -> int32_t\n    int32_min()\n\n  max_value = -> int32_t\n    int32_max()\n\n  to_int = -> int?\n    int::try_from(@)\n\n  to_int64 = -> int64_t?\n    int64_t::try_from(@)\n\n  to_uint64 = -> uint64_t?\n    uint64_t::try_from(@)\n\n  to_double = -> double\n    @ as double\n\n  to_size = -> size_t?\n    size_t::try_from(@)\n\nenchanting int64_t\n  abs = -> int64_t\n    if @ < 0 then -@ else @\n\n  min = (otro: int64_t) -> int64_t\n    if @ < otro then @ else otro\n\n  max = (otro: int64_t) -> int64_t\n    if @ > otro then @ else otro\n\n  clamp = (minimo: int64_t, maximo: int64_t) -> int64_t\n    if @ < minimo then minimo else if @ > maximo then maximo else @\n\n  sign = -> int\n    if @ > 0 then 1 else if @ < 0 then -1 else 0\n\n  is_even = -> bool\n    (@ & 1) == 0\n\n  is_odd = -> bool\n    (@ & 1) != 0\n\n  is_positive = -> bool\n    @ > 0\n\n  is_negative = -> bool\n    @ < 0\n\n  is_zero = -> bool\n    @ == 0\n\n  min_value = -> int64_t\n    int64_min()\n\n  max_value = -> int64_t\n    int64_max()\n\n  to_int = -> int?\n    int::try_from(@)\n\n  to_int64 = -> int64_t?\n    int64_t::try_from(@)\n\n  to_uint64 = -> uint64_t?\n    uint64_t::try_from(@)\n\n  to_double = -> double\n    @ as double\n\n  to_size = -> size_t?\n    size_t::try_from(@)\n\nenchanting uint8_t\n  min = (otro: uint8_t) -> uint8_t\n    if @ < otro then @ else otro\n\n  max = (otro: uint8_t) -> uint8_t\n    if @ > otro then @ else otro\n\n  clamp = (minimo: uint8_t, maximo: uint8_t) -> uint8_t\n    if @ < minimo then minimo else if @ > maximo then maximo else @\n\n  is_even = -> bool\n    (@ & 1) == 0\n\n  is_odd = -> bool\n    (@ & 1) != 0\n\n  is_positive = -> bool\n    @ > 0\n\n  is_negative = -> bool\n    @ < 0\n\n  is_zero = -> bool\n    @ == 0\n\n  min_value = -> uint8_t\n    uint8_min()\n\n  max_value = -> uint8_t\n    uint8_max()\n\n  to_int = -> int?\n    int::try_from(@)\n\n  to_int64 = -> int64_t?\n    int64_t::try_from(@)\n\n  to_uint64 = -> uint64_t?\n    uint64_t::try_from(@)\n\n  to_double = -> double\n    @ as double\n\n  to_size = -> size_t?\n    size_t::try_from(@)\n\nenchanting uint16_t\n  min = (otro: uint16_t) -> uint16_t\n    if @ < otro then @ else otro\n\n  max = (otro: uint16_t) -> uint16_t\n    if @ > otro then @ else otro\n\n  clamp = (minimo: uint16_t, maximo: uint16_t) -> uint16_t\n    if @ < minimo then minimo else if @ > maximo then maximo else @\n\n  is_even = -> bool\n    (@ & 1) == 0\n\n  is_odd = -> bool\n    (@ & 1) != 0\n\n  is_positive = -> bool\n    @ > 0\n\n  is_negative = -> bool\n    @ < 0\n\n  is_zero = -> bool\n    @ == 0\n\n  min_value = -> uint16_t\n    uint16_min()\n\n  max_value = -> uint16_t\n    uint16_max()\n\n  to_int = -> int?\n    int::try_from(@)\n\n  to_int64 = -> int64_t?\n    int64_t::try_from(@)\n\n  to_uint64 = -> uint64_t?\n    uint64_t::try_from(@)\n\n  to_double = -> double\n    @ as double\n\n  to_size = -> size_t?\n    size_t::try_from(@)\n\nenchanting uint32_t\n  min = (otro: uint32_t) -> uint32_t\n    if @ < otro then @ else otro\n\n  max = (otro: uint32_t) -> uint32_t\n    if @ > otro then @ else otro\n\n  clamp = (minimo: uint32_t, maximo: uint32_t) -> uint32_t\n    if @ < minimo then minimo else if @ > maximo then maximo else @\n\n  is_even = -> bool\n    (@ & 1) == 0\n\n  is_odd = -> bool\n    (@ & 1) != 0\n\n  is_positive = -> bool\n    @ > 0\n\n  is_negative = -> bool\n    @ < 0\n\n  is_zero = -> bool\n    @ == 0\n\n  min_value = -> uint32_t\n    uint32_min()\n\n  max_value = -> uint32_t\n    uint32_max()\n\n  to_int = -> int?\n    int::try_from(@)\n\n  to_int64 = -> int64_t?\n    int64_t::try_from(@)\n\n  to_uint64 = -> uint64_t?\n    uint64_t::try_from(@)\n\n  to_double = -> double\n    @ as double\n\n  to_size = -> size_t?\n    size_t::try_from(@)\n\nenchanting uint64_t\n  min = (otro: uint64_t) -> uint64_t\n    if @ < otro then @ else otro\n\n  max = (otro: uint64_t) -> uint64_t\n    if @ > otro then @ else otro\n\n  clamp = (minimo: uint64_t, maximo: uint64_t) -> uint64_t\n    if @ < minimo then minimo else if @ > maximo then maximo else @\n\n  is_even = -> bool\n    (@ & 1) == 0\n\n  is_odd = -> bool\n    (@ & 1) != 0\n\n  is_positive = -> bool\n    @ > 0\n\n  is_negative = -> bool\n    @ < 0\n\n  is_zero = -> bool\n    @ == 0\n\n  min_value = -> uint64_t\n    uint64_min()\n\n  max_value = -> uint64_t\n    uint64_max()\n\n  to_int = -> int?\n    int::try_from(@)\n\n  to_int64 = -> int64_t?\n    int64_t::try_from(@)\n\n  to_uint64 = -> uint64_t?\n    uint64_t::try_from(@)\n\n  to_double = -> double\n    @ as double\n\n  to_size = -> size_t?\n    size_t::try_from(@)\n",
  "std/io.pengu": "realm io\n\ninvoke \"std/string\"\n\ndeclare\n  write_values = (partes: vector<any>, nueva_linea: bool) -> void\n  eprint_values = (partes: vector<any>, nueva_linea: bool) -> void\n  read_line = -> string\n  read_all = -> string\n  flush = -> void\n  is_terminal = -> bool\n  read_char = -> char?\n\nprintln = (...partes: any) -> void\n  write_values(partes, true)\n\nprint = (...partes: any) -> void\n  write_values(partes, false)\n\neprintln = (...partes: any) -> void\n  eprint_values(partes, true)\n\neprint = (...partes: any) -> void\n  eprint_values(partes, false)\n\n  -- Lee una línea y quita el salto final.\nread_line_trimmed = -> string\n  read_line().trim_end()\n",
  "std/iter.pengu": "realm iter\n\n-- Herramientas para recorrer y transformar secuencias.\n--\n-- Los genéricos que solo aparecen en el retorno (por ejemplo el `U` de\n-- `map`) exigen argumentos de tipo explícitos: `iter::map<int, string>`.\n-- Es la decisión D2 del plan de la biblioteca estándar.\n\ninvoke \"std/vector\"\ninvoke \"std/optional\"\ninvoke \"std/pair\"\n\n-- Aplica `f` a cada elemento.\nmap = <T, U>(items: ref<vector<T>>, f: function<(T) -> U>) -> vector<U>\n  mut salida: vector<U> = []\n  for item in items\n    salida.push(f(item))\n  salida\n\n  -- Se queda con los elementos que cumplen `f`.\nfilter = <T>(items: ref<vector<T>>, f: function<(T) -> bool>) -> vector<T>\n  mut salida: vector<T> = []\n  for item in items\n    if f(item)\n      salida.push(item)\n  salida\n\n  -- Reduce la secuencia a un único valor.\nfold = <T, A>(items: ref<vector<T>>, inicial: A, f: function<(A, T) -> A>) -> A\n  mut acumulado = inicial\n  for item in items\n    acumulado = f(acumulado, item)\n  acumulado\n\n  -- Cuenta los elementos que cumplen `f`.\ncount_if = <T>(items: ref<vector<T>>, f: function<(T) -> bool>) -> size_t\n  mut total: int = 0\n  for item in items\n    if f(item)\n      total += 1\n  size_t:: from (total)\n\n  -- ¿Hay algún elemento que cumpla `f`?\nany = <T>(items: ref<vector<T>>, f: function<(T) -> bool>) -> bool\n  for item in items\n    if f(item)\n      return true\n  false\n\n  -- ¿Todos los elementos cumplen `f`?\nall = <T>(items: ref<vector<T>>, f: function<(T) -> bool>) -> bool\n  for item in items\n    if not f(item)\n      return false\n  true\n\n  -- ¿Ningún elemento cumple `f`?\nnone_of = <T>(items: ref<vector<T>>, f: function<(T) -> bool>) -> bool\n  not any(items, f)\n\n  -- Primer elemento que cumple `f`.\nfind = <T>(items: ref<vector<T>>, f: function<(T) -> bool>) -> T?\n  for item in items\n    if f(item)\n      return item\n  none\n\n  -- Posición del primer elemento que cumple `f`.\nposition = <T>(items: ref<vector<T>>, f: function<(T) -> bool>) -> size_t?\n  mut indice: int = 0\n  for item in items\n    if f(item)\n      return size_t:: from (indice)\n    indice += 1\n  none\n\n  -- Empareja dos secuencias hasta la más corta.\nzip = <A, B>(a: ref<vector<A>>, b: ref<vector<B>>) -> vector<pair<A, B>>\n  mut salida: vector<pair<A, B>> = []\n  mut indice: int = 0\n  while indice < #a and indice < #b\n    mut par: pair<A, B> = (a[indice], b[indice])\n    salida.push(par)\n    indice += 1\n  salida\n\n  -- Añade la posición a cada elemento.\nenumerate = <T>(items: ref<vector<T>>) -> vector<pair<size_t, T>>\n  mut salida: vector<pair<size_t, T>> = []\n  mut indice: int = 0\n  for item in items\n    mut par: pair<size_t, T> = (size_t:: from (indice), item)\n    salida.push(par)\n    indice += 1\n  salida\n\n  -- Los primeros `cantidad` elementos.\ntake = <T>(items: ref<vector<T>>, cantidad: size_t) -> vector<T>\n  mut salida: vector<T> = []\n  mut indice = 0\n  while indice < #items and size_t:: from (indice) < cantidad\n    salida.push(items[indice])\n    indice += 1\n  salida\n\n  -- Todo menos los primeros `cantidad` elementos.\nskip = <T>(items: ref<vector<T>>, cantidad: size_t) -> vector<T>\n  mut salida: vector<T> = []\n  mut indice = 0\n  while indice < #items\n    if size_t:: from (indice) >= cantidad\n      salida.push(items[indice])\n    indice += 1\n  salida\n\n  -- Concatena dos secuencias.\nchain = <T>(a: ref<vector<T>>, b: ref<vector<T>>) -> vector<T>\n  mut salida: vector<T> = []\n  for item in a\n    salida.push(item)\n  for item in b\n    salida.push(item)\n  salida\n\n  -- Aplana una secuencia de secuencias.\nflatten = <T>(items: ref<vector<vector<T>>>) -> vector<T>\n  mut salida: vector<T> = []\n  for grupo in items\n    for item in grupo\n      salida.push(item)\n  salida\n",
  "std/log.pengu": "realm log\n\ndeclare\n  log_values = (nivel: string, partes: vector<any>) -> void\n  set_level_raw = (nivel: string) -> void\n  level_raw = -> string\n  enabled_raw = (nivel: string) -> bool\n  timestamped_raw = (activo: bool) -> void\n\n  -- Niveles de registro, de menos a más grave.\nomen Level\n  Debug\n  Info\n  Warn\n  Error\n\nenchanting Level\n  name = -> string\n    if @ == Level::Debug\n      return \"debug\"\n    if @ == Level::Info\n      return \"info\"\n    if @ == Level::Warn\n      return \"warn\"\n    \"error\"\n\n  to_int = -> int\n    if @ == Level::Debug\n      return 0\n    if @ == Level::Info\n      return 1\n    if @ == Level::Warn\n      return 2\n    3\n\ndebug = (...partes: any) -> void\n  log_values(\"debug\", partes)\n\ninfo = (...partes: any) -> void\n  log_values(\"info\", partes)\n\nwarn = (...partes: any) -> void\n  log_values(\"warn\", partes)\n\nerror = (...partes: any) -> void\n  log_values(\"error\", partes)\n\nset_level = (nivel: Level) -> void\n  set_level_raw(nivel.name())\n\nlevel = -> Level\n  nombre = level_raw()\n  if nombre == \"debug\"\n    return Level::Debug\n  if nombre == \"info\"\n    return Level::Info\n  if nombre == \"warn\"\n    return Level::Warn\n  Level::Error\n\nenabled = (nivel: Level) -> bool\n  enabled_raw(nivel.name())\n\ntimestamped = (activo: bool) -> void\n  timestamped_raw(activo)\n",
  "std/long_double.pengu": "realm long_double\n\ninvoke \"std/math\"\n\n-- Primitivas específicas de «long double»: las de <cmath> tienen una sobrecarga\n-- por ancho, así que el resultado conserva el tipo.\ndeclare\n  sqrt = (x: long double) -> long double\n  cbrt = (x: long double) -> long double\n  pow = (base: long double, exponent: long double) -> long double\n  exp = (x: long double) -> long double\n  ln = (x: long double) -> long double\n  log2 = (x: long double) -> long double\n  log10 = (x: long double) -> long double\n  floor = (x: long double) -> long double\n  ceil = (x: long double) -> long double\n  round = (x: long double) -> long double\n  trunc = (x: long double) -> long double\n  hypot = (x: long double, y: long double) -> long double\n  is_finite = (x: long double) -> bool\n  is_infinite = (x: long double) -> bool\n  is_nan = (x: long double) -> bool\n  is_sign_negative = (x: long double) -> bool\n  to_fixed = (x: long double, decimals: int) -> string\n  to_scientific = (x: long double, decimals: int) -> string\n\nenchanting long double\n  abs = -> long double\n    if @ < 0.0 then -@ else @\n\n  min = (otro: long double) -> long double\n    if @ < otro then @ else otro\n\n  max = (otro: long double) -> long double\n    if @ > otro then @ else otro\n\n  clamp = (minimo: long double, maximo: long double) -> long double\n    if @ < minimo then minimo else if @ > maximo then maximo else @\n\n  is_positive = -> bool\n    @ > 0.0\n\n  is_negative = -> bool\n    @ < 0.0\n\n  is_zero = -> bool\n    @ == 0.0\n\n  between = (minimo: long double, maximo: long double) -> bool\n    @ >= minimo and @ <= maximo\n\n  sqrt = -> long double\n    sqrt(@)\n\n  cbrt = -> long double\n    cbrt(@)\n\n  pow = (exponente: long double) -> long double\n    pow(@, exponente)\n\n  exp = -> long double\n    exp(@)\n\n  ln = -> long double\n    ln(@)\n\n  log2 = -> long double\n    log2(@)\n\n  log10 = -> long double\n    log10(@)\n\n  floor = -> long double\n    floor(@)\n\n  ceil = -> long double\n    ceil(@)\n\n  round = -> long double\n    round(@)\n\n  trunc = -> long double\n    trunc(@)\n\n  fract = -> long double\n    @ - floor(@)\n\n  round_to = (decimales: int) -> long double\n    factor = pow(10 as long double, decimales as long double)\n    round(@ * factor) / factor\n\n  hypot = (otro: long double) -> long double\n    hypot(@, otro)\n\n  is_finite = -> bool\n    is_finite(@)\n\n  is_infinite = -> bool\n    is_infinite(@)\n\n  is_nan = -> bool\n    is_nan(@)\n\n  is_sign_negative = -> bool\n    is_sign_negative(@)\n\n  signum = -> long double\n    if @ > 0.0 then 1.0 else if @ < 0.0 then -1.0 else 0.0\n\n  lerp = (hacia: long double, t: long double) -> long double\n    @ + (hacia - @) * t\n\n  approx_eq = (otro: long double, epsilon: long double = 1e-6) -> bool\n    (@ - otro).abs() <= epsilon\n\n  to_fixed = (decimales: int) -> string\n    to_fixed(@, decimales)\n\n  to_scientific = (decimales: int) -> string\n    to_scientific(@, decimales)\n\n  to_double = -> double?\n    double::try_from(@)\n\n  to_float = -> float?\n    float::try_from(@)\n\n  to_int = -> int?\n    int::try_from(@)\n",
  "std/map.pengu": "realm map\n\ninvoke \"std/pair\"\n\nenchanting map<K, V>\n  is_empty = -> bool\n    #@ == 0\n\n  contains_key = (clave: K) -> bool\n    clave in @\n\n  keys_list = -> vector<K>\n    mut salida: vector<K> = []\n    for clave, _ in @\n      salida.push(clave)\n    salida\n\n  values_list = -> vector<V>\n    mut salida: vector<V> = []\n    for _, valor in @\n      salida.push(valor)\n    salida\n\n  mut get_or_insert = (clave: K, alternativa: V) -> V\n    if clave in @\n      return @[clave]\n    @.insert(clave, alternativa)\n    alternativa\n\n  mut update = (clave: K, cambiar: function<(V) -> V>) -> bool\n    if not (clave in @)\n      return false\n    @[clave] = cambiar(@[clave])\n    true\n\n  entries = -> vector<pair<K, V>>\n    mut salida: vector<pair<K, V>> = []\n    for clave, valor in @\n      mut par: pair<K, V> = (clave, valor)\n      salida.push(par)\n    salida\n\n  first_key = -> K?\n    for clave, _ in @\n      return clave\n    none\n\n  last_key = -> K?\n    mut ultima: K? = none\n    for clave, _ in @\n      ultima = clave\n    ultima\n\n  mut merge = (otro: ref<map<K, V>>) -> void\n    for clave, valor in otro\n      if not (clave in @)\n        @.insert(clave, valor)\n\n  mut retain = (predicado: function<(K, V) -> bool>) -> void\n    mut conservados: map<K, V> = map{}\n    for clave, valor in @\n      if predicado(clave, valor)\n        conservados.insert(clave, valor)\n    @ = conservados\n",
  "std/math.pengu": "realm math\n\n-- Constantes que se usan a diario en física, gráficos y simulaciones.\nconst pi: double = 3.141592653589793\nconst e: double = 2.718281828459045\nconst tau: double = 6.283185307179586\nconst phi: double = 1.618033988749895\nconst sqrt2: double = 1.4142135623730951\nconst ln2: double = 0.6931471805599453\nconst ln10: double = 2.302585092994046\nconst radians_per_degree: double = 0.017453292519943295\nconst degrees_per_radian: double = 57.29577951308232\n\n-- Primitivas del runtime: cada una se traduce a una función de <cmath>.\ndeclare\n  abs = (x: double) -> double\n  sqrt = (x: double) -> double\n  cbrt = (x: double) -> double\n  floor = (x: double) -> double\n  ceil = (x: double) -> double\n  round = (x: double) -> double\n  trunc = (x: double) -> double\n  nearbyint = (x: double) -> double\n  sin = (x: double) -> double\n  cos = (x: double) -> double\n  tan = (x: double) -> double\n  asin = (x: double) -> double\n  acos = (x: double) -> double\n  atan = (x: double) -> double\n  atan2 = (y: double, x: double) -> double\n  sinh = (x: double) -> double\n  cosh = (x: double) -> double\n  tanh = (x: double) -> double\n  asinh = (x: double) -> double\n  acosh = (x: double) -> double\n  atanh = (x: double) -> double\n  exp = (x: double) -> double\n  exp2 = (x: double) -> double\n  expm1 = (x: double) -> double\n  ln = (x: double) -> double\n  log2 = (x: double) -> double\n  log10 = (x: double) -> double\n  log1p = (x: double) -> double\n  pow = (base: double, exponent: double) -> double\n  hypot = (x: double, y: double) -> double\n  fmod = (x: double, y: double) -> double\n  remainder = (x: double, y: double) -> double\n  fdim = (x: double, y: double) -> double\n  fmax = (x: double, y: double) -> double\n  fmin = (x: double, y: double) -> double\n  copysign = (magnitude: double, sign: double) -> double\n  fma = (x: double, y: double, z: double) -> double\n  min = (a: double, b: double) -> double\n  max = (a: double, b: double) -> double\n  clamp = (value: double, low: double, high: double) -> double\n  signbit = (x: double) -> bool\n  is_finite = (x: double) -> bool\n  is_infinite = (x: double) -> bool\n  is_nan = (x: double) -> bool\n  infinite = () -> double\n  not_a_number = () -> double\n  gcd = (a: int, b: int) -> int\n  lcm = (a: int, b: int) -> int\n\n  -- Utilidades puras de física y juegos. Todas son const-evaluables cuando\n  -- sus argumentos lo son.\nlerp = (a: double, b: double, t: double) -> double\n  a + (b - a) * t\n\ninverse_lerp = (a: double, b: double, value: double) -> double\n  if a == b then 0.0 else (value - a) / (b - a)\n\nremap = (value: double, in_low: double, in_high: double, out_low: double, out_high: double) -> double\n  lerp(out_low, out_high, inverse_lerp(in_low, in_high, value))\n\nclamp01 = (value: double) -> double\n  clamp(value, 0.0, 1.0)\n\nsign = (value: double) -> double\n  if value > 0.0 then 1.0 else if value < 0.0 then -1.0 else 0.0\n\nsmoothstep = (edge0: double, edge1: double, x: double) -> double\n  t = clamp01((x - edge0) / (edge1 - edge0))\n  t * t * (3.0 - 2.0 * t)\n\nsmootherstep = (edge0: double, edge1: double, x: double) -> double\n  t = clamp01((x - edge0) / (edge1 - edge0))\n  t * t * t * (t * (t * 6.0 - 15.0) + 10.0)\n\ndeg_to_rad = (grados: double) -> double\n  grados * radians_per_degree\n\nrad_to_deg = (radianes: double) -> double\n  radianes * degrees_per_radian\n\n  -- Envuelve `value` en [low, high), sin bucles ni desbordamiento.\nwrap = (value: double, low: double, high: double) -> double\n  span = high - low\n  low + (value - low) - span * floor((value - low) / span)\n\n  -- Envuelve un ángulo a [-pi, pi).\nwrap_angle = (angulo: double) -> double\n  wrap(angulo, -pi, pi)\n\n  -- Interpolación angular por el camino corto.\nlerp_angle = (a: double, b: double, t: double) -> double\n  a + wrap_angle(b - a) * t\n\nmove_towards = (actual: double, objetivo: double, paso: double) -> double\n  if abs(objetivo - actual) <= paso then objetivo else actual + sign(objetivo - actual) * paso\n\n  -- Suavizado independiente del paso de tiempo (Frame Rate Independent Damping).\ndamp = (actual: double, objetivo: double, lambda: double, dt: double) -> double\n  lerp(actual, objetivo, 1.0 - exp(-lambda * dt))\n\napprox_eq = (a: double, b: double, epsilon: double = 1e-9) -> bool\n  abs(a - b) <= epsilon\n\nmin3 = (a: double, b: double, c: double) -> double\n  min(min(a, b), c)\n\nmax3 = (a: double, b: double, c: double) -> double\n  max(max(a, b), c)\n\naverage = (a: double, b: double) -> double\n  (a + b) * 0.5\n\n  -- Potencia entera por cuadrados: exacta y sin depender de `pow`.\nipow = (base: int, exponente: int) -> int\n  if exponente < 0\n    return 0\n  mut resultado = 1\n  mut b = base\n  mut e = exponente\n  while e > 0\n    if e % 2 == 1\n      resultado *= b\n    b *= b\n    e /= 2\n  resultado\n\nis_power_of_two = (value: int) -> bool\n  value > 0 and (value & (value - 1)) == 0\n\nnext_power_of_two = (value: int) -> int\n  if value <= 1\n    return 1\n  mut resultado = 1\n  while resultado < value\n    resultado *= 2\n  resultado\n\nalign_up = (value: int, align: int) -> int\n  if align <= 1 then value else ((value + align - 1) / align) * align\n",
  "std/memory.pengu": "realm memory\n\nenchanting unique<T>\n  get = -> ref<T>\n    ref(@)\n\n  mut set = (valor: T) -> void\n    @ = valor\n\nenchanting shared<T>\n  get = -> ref<T>\n    ref(@)\n\n  mut set = (valor: T) -> void\n    @ = valor\n\nenchanting weak<T>\n  is_alive = -> bool\n    @.lock().is_some()\n",
  "std/noise.pengu": "-- Ruido de valor determinista: sirve para terreno, texturas y temblores.\n--\n-- Es una función pura de (coordenada, semilla): la misma entrada da\n-- siempre el mismo resultado, sin estado global. El ruido fractal suma\n-- varias octavas y normaliza el resultado a 0..1.\ninvoke \"std/int\"\ninvoke \"std/math\"\n\n-- Hash clásico de GLSL: estable, barato y suficiente para juegos.\nhash = (x: double, y: double, semilla: int) -> double\n  valor = math::sin(x * 127.1 + y * 311.7 + semilla.to_double() * 74.7) * 43758.5453123\n  valor - math::floor(valor)\n\nsuavizar = (t: double) -> double\n  t * t * (3.0 - 2.0 * t)\n\nmezclar = (a: double, b: double, t: double) -> double\n  a + (b - a) * t\n\nvalue_1d = (x: double, semilla: int = 0) -> double\n  celda = math::floor(x)\n  resto = x - celda\n  izquierda = hash(celda, 0.0, semilla)\n  derecha = hash(celda + 1.0, 0.0, semilla)\n  mezclar(izquierda, derecha, suavizar(resto))\n\nvalue_2d = (x: double, y: double, semilla: int = 0) -> double\n  celda_x = math::floor(x)\n  celda_y = math::floor(y)\n  resto_x = x - celda_x\n  resto_y = y - celda_y\n  arriba_izquierda = hash(celda_x, celda_y, semilla)\n  arriba_derecha = hash(celda_x + 1.0, celda_y, semilla)\n  abajo_izquierda = hash(celda_x, celda_y + 1.0, semilla)\n  abajo_derecha = hash(celda_x + 1.0, celda_y + 1.0, semilla)\n  arriba = mezclar(arriba_izquierda, arriba_derecha, suavizar(resto_x))\n  abajo = mezclar(abajo_izquierda, abajo_derecha, suavizar(resto_x))\n  mezclar(arriba, abajo, suavizar(resto_y))\n\nsigned_2d = (x: double, y: double, semilla: int = 0) -> double\n  value_2d(x, y, semilla) * 2.0 - 1.0\n\nfractal_2d = (x: double, y: double, octavas: int, semilla: int = 0, lacunaridad: double = 2.0, ganancia: double = 0.5) -> double\n  if octavas <= 0\n    return 0.0\n  mut total = 0.0\n  mut amplitud = 1.0\n  mut frecuencia = 1.0\n  mut normalizacion = 0.0\n  mut i = 0\n  while i < octavas\n    total += value_2d(x * frecuencia, y * frecuencia, semilla + i) * amplitud\n    normalizacion += amplitud\n    amplitud *= ganancia\n    frecuencia *= lacunaridad\n    i += 1\n  if normalizacion == 0.0\n    return 0.0\n  total / normalizacion\n\nturbulence_2d = (x: double, y: double, octavas: int, semilla: int = 0, lacunaridad: double = 2.0, ganancia: double = 0.5) -> double\n  if octavas <= 0\n    return 0.0\n  mut total = 0.0\n  mut amplitud = 1.0\n  mut frecuencia = 1.0\n  mut normalizacion = 0.0\n  mut i = 0\n  while i < octavas\n    onda = value_2d(x * frecuencia, y * frecuencia, semilla + i)\n    total += math::abs(onda * 2.0 - 1.0) * amplitud\n    normalizacion += amplitud\n    amplitud *= ganancia\n    frecuencia *= lacunaridad\n    i += 1\n  if normalizacion == 0.0\n    return 0.0\n  total / normalizacion\n\nridged_2d = (x: double, y: double, octavas: int, semilla: int = 0) -> double\n  1.0 - turbulence_2d(x, y, octavas, semilla)\n",
  "std/optional.pengu": "realm optional\n\nenchanting optional<T>\n  is_empty = -> bool\n    @.is_none()\n\n  or_else = (alternativa: T) -> T\n    if @.is_some() then @.value() else alternativa\n\n  filter = (predicado: function<(T) -> bool>) -> T?\n    if @.is_some() and predicado(@.value()) then @.value() else none\n\n  to_vector = -> vector<T>\n    mut salida: vector<T> = []\n    if @.is_some()\n      salida.push(@.value())\n    salida\n\n  map = (transformar: function<(T) -> T>) -> T?\n    if @.is_some() then transformar(@.value()) else none\n\n  and_then = (siguiente: function<(T) -> T?>) -> T?\n    if @.is_some()\n      return siguiente(@.value())\n    none\n\n  or_else_get = (alternativa: function<() -> T>) -> T\n    if @.is_some() then @.value() else alternativa()\n\n  zip = (otro: T?) -> pair<T, T>?\n    if @.is_some() and otro.is_some()\n      mut par: pair<T, T> = (@.value(), otro.value())\n      return par\n    none\n\n  any = (predicado: function<(T) -> bool>) -> bool\n    if @.is_some() then predicado(@.value()) else false\n",
  "std/ordering.pengu": "realm ordering\n\nenchanting Ordering\n  then = (otro: Ordering) -> Ordering\n    if @ == Ordering::Equal then otro else @\n\n  to_int = -> int\n    if @ == Ordering::Less\n      return -1\n    if @ == Ordering::Equal\n      return 0\n    1\n\n  then_with = (siguiente: function<() -> Ordering>) -> Ordering\n    if @ == Ordering::Equal then siguiente() else @\n",
  "std/os.pengu": "realm os\n\ndeclare\n  args = -> vector<string>\n  get_env = (nombre: string) -> string?\n  set_env = (nombre: string, valor: string) -> bool\n  exit = (codigo: int) -> void\n  pid = -> int\n  home_dir = -> string?\n  temp_dir = -> string?\n  current_dir = -> string?\n  platform = -> string\n  arch = -> string\n  cpu_count = -> int\n\n  -- Variable de entorno con valor por defecto.\nenv_or = (nombre: string, respaldo: string) -> string\n  valor = get_env(nombre)\n  if valor.is_some() then valor.value() else respaldo\n\nhas_env = (nombre: string) -> bool\n  get_env(nombre).is_some()\n",
  "std/pair.pengu": "realm pair\n\nenchanting pair<A, B>\n  swap = -> pair<B, A>\n    (@.second, @.first)\n\n  to_tuple = -> tuple<A, B>\n    (@.first, @.second)\n",
  "std/path.pengu": "realm path\n\ninvoke \"std/string\"\ninvoke \"std/vector\"\n\nseparator: string = \"/\"\n\nis_absolute = (ruta: string) -> bool\n  ruta.starts_with(separator)\n\njoin = (base: string, resto: string) -> string\n  if base.is_empty()\n    return resto\n  if resto.is_empty()\n    return base\n  if resto.starts_with(separator)\n    return resto\n  if base.ends_with(separator)\n    return base + resto\n  base + separator + resto\n\njoin_all = (partes: ref<vector<string>>) -> string\n  mut salida = \"\"\n  for parte in partes\n    salida = join(salida, parte)\n  salida\n\nfile_name = (ruta: string) -> string?\n  mut fin: size_t = #ruta\n  while fin > 0 and ruta[fin - 1] == '/'\n    fin -= 1\n  if fin == 0\n    return none\n  mut inicio: size_t = fin\n  while inicio > 0 and ruta[inicio - 1] != '/'\n    inicio -= 1\n  ruta.substr(inicio, fin - inicio)\n\nextension = (ruta: string) -> string?\n  nombre = file_name(ruta)\n  if nombre.is_none()\n    return none\n  texto = nombre.value()\n  posicion = texto.rfind(\".\")\n  if posicion.is_none()\n    return none\n  if posicion.value() == 0\n    return none\n  texto.substr(posicion.value() + 1, #texto - posicion.value() - 1)\n\nstem = (ruta: string) -> string?\n  nombre = file_name(ruta)\n  if nombre.is_none()\n    return none\n  texto = nombre.value()\n  posicion = texto.rfind(\".\")\n  if posicion.is_none()\n    return texto\n  if posicion.value() == 0\n    return texto\n  texto.substr(0, posicion.value())\n\nparent_dir = (ruta: string) -> string?\n  mut fin: size_t = #ruta\n  while fin > 1 and ruta[fin - 1] == '/'\n    fin -= 1\n  mut i: size_t = fin\n  mut corte: size_t = 0\n  mut encontrado = false\n  while i > 0 and not encontrado\n    i -= 1\n    if ruta[i] == '/'\n      corte = i\n      encontrado = true\n  if not encontrado\n    return none\n  if corte == 0\n    return \"/\"\n  ruta.substr(0, corte)\n\nwith_extension = (ruta: string, nueva: string) -> string\n  base = stem(ruta)\n  if base.is_none()\n    return ruta\n  carpeta = parent_dir(ruta)\n  if nueva.is_empty()\n    if carpeta.is_some()\n      return join(carpeta.value(), base.value())\n    return base.value()\n  if nueva.starts_with(\".\")\n    if carpeta.is_some()\n      return join(carpeta.value(), \"#{base.value()}#{nueva}\")\n    return \"#{base.value()}#{nueva}\"\n  if carpeta.is_some()\n    return join(carpeta.value(), \"#{base.value()}.#{nueva}\")\n  \"#{base.value()}.#{nueva}\"\n\n  -- Colapsa «//», «.» y «..» sin tocar el disco.\nnormalize = (ruta: string) -> string\n  absoluta = ruta.starts_with(\"/\")\n  mut partes: vector<string> = []\n  for parte in ruta.split(\"/\")\n    if not parte.is_empty() and parte != \".\"\n      if parte == \"..\"\n        if not partes.is_empty()\n          partes.resize(#partes - 1)\n        else if not absoluta\n          partes.push(\"..\")\n      else\n        partes.push(parte)\n  if partes.is_empty()\n    if absoluta then \"/\" else \".\"\n  else\n    mut salida = partes.join(\"/\")\n    if absoluta\n      salida = \"/\" + salida\n    salida\n\ncomponents = (ruta: string) -> vector<string>\n  mut partes: vector<string> = []\n  for parte in ruta.split(\"/\")\n    if not parte.is_empty()\n      partes.push(parte)\n  partes\n",
  "std/physics.pengu": "-- Cuerpos rígidos muy sencillos: integración, gravedad y rebotes.\n--\n-- Es física de juego, no simulación: sin rotación ni fricción real, con\n-- amortiguación y rebote configurables. Todo se mide en unidades del\n-- juego (píxeles, metros) por segundo.\ninvoke \"std/geometry\"\ninvoke \"std/int\"\ninvoke \"std/math\"\n\nrune Body\n  position: geometry::Vec2\n  velocity: geometry::Vec2\n  mass: double\n  restitution: double\n\n  constructor(position: geometry::Vec2, velocity: geometry::Vec2, mass: double, restitution: double)\n    @position = position\n    @velocity = velocity\n    @mass = mass\n    @restitution = restitution\n\nenchanting Body\n  speed = -> double\n    @velocity.length()\n\n  is_moving = -> bool\n    not @velocity.is_zero()\n\n  momentum = -> geometry::Vec2\n    @velocity * @mass\n\n  kinetic_energy = -> double\n    0.5 * @mass * @velocity.length_squared()\n\n  mut apply_force = (fuerza: geometry::Vec2, dt: double) -> void\n    if @mass <= 0.0\n      return\n    @velocity = @velocity + fuerza * (dt / @mass)\n\n  mut apply_impulse = (impulso: geometry::Vec2) -> void\n    if @mass <= 0.0\n      return\n    @velocity = @velocity + impulso * (1.0 / @mass)\n\n  mut apply_gravity = (gravedad: geometry::Vec2, dt: double) -> void\n    @velocity = @velocity + gravedad * dt\n\n  mut integrate = (dt: double) -> void\n    @position = @position + @velocity * dt\n\n  mut damp = (coeficiente: double, dt: double) -> void\n    if coeficiente <= 0.0\n      return\n    factor = math::max(0.0, 1.0 - coeficiente * dt)\n    @velocity = @velocity * factor\n\n  mut bounce_floor = (suelo: double, restitucion: double) -> void\n    if @position.y > suelo or @velocity.y >= 0.0\n      return\n    @position = geometry::Vec2(@position.x, suelo)\n    @velocity = geometry::Vec2(@velocity.x, -@velocity.y * restitucion)\n\n  mut bounce_bounds = (ancho: double, alto: double, restitucion: double) -> void\n    if @position.x < 0.0\n      @position = geometry::Vec2(0.0, @position.y)\n      @velocity = geometry::Vec2(-@velocity.x * restitucion, @velocity.y)\n    if @position.x > ancho\n      @position = geometry::Vec2(ancho, @position.y)\n      @velocity = geometry::Vec2(-@velocity.x * restitucion, @velocity.y)\n    if @position.y < 0.0\n      @position = geometry::Vec2(@position.x, 0.0)\n      @velocity = geometry::Vec2(@velocity.x, -@velocity.y * restitucion)\n    if @position.y > alto\n      @position = geometry::Vec2(@position.x, alto)\n      @velocity = geometry::Vec2(@velocity.x, -@velocity.y * restitucion)\n\n  mut stop = -> void\n    @velocity = geometry::Vec2(0.0, 0.0)\n\n  to_string = -> string\n    \"Body(#{@position}, #{@velocity}, m=#{@mass}, e=#{@restitution})\"\n\n    -- Constructores libres.\n\nbody = (posicion: geometry::Vec2, velocidad: geometry::Vec2, masa: double, restitucion: double) -> Body\n  Body(posicion, velocidad, masa, restitucion)\n\nbody_at = (posicion: geometry::Vec2) -> Body\n  Body(posicion, geometry::Vec2(0.0, 0.0), 1.0, 0.5)\n\nbody_moving = (posicion: geometry::Vec2, velocidad: geometry::Vec2) -> Body\n  Body(posicion, velocidad, 1.0, 0.5)\n\n  -- Fuerza de gravedad sobre una masa: `F = m · g`.\ngravity_force = (masa: double, gravedad: geometry::Vec2) -> geometry::Vec2\n  gravedad * masa\n\n  -- Paso completo de simulación: gravedad, amortiguación e integración.\n  --\n  -- Devuelve el cuerpo en vez de mutarlo por referencia para que el bucle de\n  -- juego sea una expresión: `cuerpo = physics::step(cuerpo, gravedad, 0.0, 0.016)`.\nstep = (cuerpo: Body, gravedad: geometry::Vec2, amortiguacion: double, dt: double) -> Body\n  mut copia = cuerpo\n  copia.apply_gravity(gravedad, dt)\n  copia.damp(amortiguacion, dt)\n  copia.integrate(dt)\n  copia\n",
  "std/random.pengu": "realm random\n\ninvoke \"std/time\"\n\ndeclare\n  int = (minimo: int, maximo: int) -> int\n  float = -> double\n  bool = -> bool\n  seed = (semilla: int64_t) -> void\n  float_range = (minimo: double, maximo: double) -> double\n\n  -- `true` con probabilidad `probabilidad` (0.0 a 1.0).\nchance = (probabilidad: double) -> bool\n  float() < probabilidad\n\n  -- Elige con reparto uniforme entre `desde` y `hasta`, ambos incluidos.\nint_range = (desde: int, hasta: int) -> int\n  int(desde, hasta)\n\n  -- Semilla a partir del reloj: útil para una partida nueva.\nseed_from_time = -> void\n  seed(time::now_millis())\n",
  "std/result.pengu": "realm result\n\n-- Resultados explícitos: un valor o un error, sin excepciones.\n--\n-- `B` es el tipo del error. Los genéricos que solo aparecen en el retorno\n-- (`ok<U, E>(...)`) se pasan con argumentos de tipo explícitos (D2).\n\ninvoke \"std/optional\"\ninvoke \"std/assert\"\n\nrune Result<T, E>\n  dato: T?\n  fallo: E?\n\n  constructor(dato: T?, fallo: E?)\n    @dato = dato\n    @fallo = fallo\n\n    -- Un resultado correcto.\nok = <T, E>(dato: T) -> Result<T, E>\n  mut resultado: Result<T, E> = Result<T, E>(dato, none)\n  resultado\n\n  -- Un resultado con error.\nerr = <T, E>(fallo: E) -> Result<T, E>\n  mut resultado: Result<T, E> = Result<T, E>( none, fallo)\n  resultado\n\nenchanting Result\n  is_ok = -> bool\n    @.dato.is_some()\n\n  is_err = -> bool\n    @.fallo.is_some()\n\n    -- El valor o un respaldo.\n  value_or = (respaldo: T) -> T\n    if @.dato.is_some()\n      return @.dato.value()\n    respaldo\n\n    -- El valor; panica si es un error.\n  value = -> T\n    if @.fallo.is_some()\n      assert::fail(\"result::value sobre un Err\")\n    @.dato.value()\n\n    -- El error o un respaldo.\n  error_or = (respaldo: E) -> E\n    if @.fallo.is_some()\n      return @.fallo.value()\n    respaldo\n\n    -- El error; panica si es un valor.\n  error = -> E\n    if @.dato.is_some()\n      assert::fail(\"result::error sobre un Ok\")\n    @.fallo.value()\n\n    -- El valor; panica con `mensaje` si es un error.\n  expect = (mensaje: string) -> T\n    if @.fallo.is_some()\n      assert::fail(mensaje)\n    @.dato.value()\n\n  to_string = -> string\n    if @.dato.is_some()\n      return \"Ok(#{@.dato.value()})\"\n    \"Err(#{@.fallo.value()})\"\n\n    -- Transforma el valor de un `Ok` y propaga el error.\nmap = <T, U, E>(resultado: Result<T, E>, f: function<(T) -> U>) -> Result<U, E>\n  if resultado.is_err()\n    return err<U, E>(resultado.error())\n  ok<U, E>(f(resultado.value()))\n\n  -- Transforma el error de un `Err` y conserva el valor.\nmap_err = <T, E, U>(resultado: Result<T, E>, f: function<(E) -> U>) -> Result<T, U>\n  if resultado.is_ok()\n    return ok<T, U>(resultado.value())\n  err<T, U>(f(resultado.error()))\n\n  -- Encadena dos operaciones que pueden fallar.\nand_then = <T, U, E>(resultado: Result<T, E>, f: function<(T) -> Result<U, E>>) -> Result<U, E>\n  if resultado.is_err()\n    return err<U, E>(resultado.error())\n  f(resultado.value())\n\n  -- Convierte un `optional` en un resultado, con el error indicado.\nfrom_optional = <T, E>(valor: T?, fallo: E) -> Result<T, E>\n  if valor.is_some()\n    return ok<T, E>(valor.value())\n  err<T, E>(fallo)\n",
  "std/set.pengu": "realm set\n\nenchanting set<T>\n  is_empty = -> bool\n    #@ == 0\n\n  contains = (valor: T) -> bool\n    valor in @\n\n  to_vector = -> vector<T>\n    mut salida: vector<T> = []\n    for valor in @\n      salida.push(valor)\n    salida\n\n  union = (otro: ref<set<T>>) -> set<T>\n    mut salida: set<T> = set{}\n    for valor in @\n      salida.insert(valor)\n    for valor in otro\n      salida.insert(valor)\n    salida\n\n  intersection = (otro: ref<set<T>>) -> set<T>\n    mut salida: set<T> = set{}\n    for valor in @\n      if valor in otro\n        salida.insert(valor)\n    salida\n\n  difference = (otro: ref<set<T>>) -> set<T>\n    mut salida: set<T> = set{}\n    for valor in @\n      if not (valor in otro)\n        salida.insert(valor)\n    salida\n\n  symmetric_difference = (otro: ref<set<T>>) -> set<T>\n    mut salida: set<T> = set{}\n    for valor in @\n      if not (valor in otro)\n        salida.insert(valor)\n    for valor in otro\n      if not (valor in @)\n        salida.insert(valor)\n    salida\n\n  is_subset = (otro: ref<set<T>>) -> bool\n    for valor in @\n      if not (valor in otro)\n        return false\n    true\n\n  is_superset = (otro: ref<set<T>>) -> bool\n    for valor in otro\n      if not (valor in @)\n        return false\n    true\n\n  is_disjoint = (otro: ref<set<T>>) -> bool\n    for valor in @\n      if valor in otro\n        return false\n    true\n\n  mut insert_all = (otro: ref<set<T>>) -> void\n    for valor in otro\n      @.insert(valor)\n\n  mut remove_all = (otro: ref<set<T>>) -> void\n    for valor in otro\n      @.remove(valor)\n\n  mut extend = (valores: ref<vector<T>>) -> void\n    for valor in valores\n      @.insert(valor)\n\n  mut retain = (predicado: function<(T) -> bool>) -> void\n    mut conservados: set<T> = set{}\n    for valor in @\n      if predicado(valor)\n        conservados.insert(valor)\n    @ = conservados\n\n  first = -> T?\n    for valor in @\n      return valor\n    none\n\n  last = -> T?\n    mut ultimo: T? = none\n    for valor in @\n      ultimo = valor\n    ultimo\n\n  map = (transformar: function<(T) -> T>) -> set<T>\n    mut salida: set<T> = set{}\n    for valor in @\n      salida.insert(transformar(valor))\n    salida\n\n  filter = (predicado: function<(T) -> bool>) -> set<T>\n    mut salida: set<T> = set{}\n    for valor in @\n      if predicado(valor)\n        salida.insert(valor)\n    salida\n\n  to_sorted_vector = -> vector<T>\n    mut salida: vector<T> = []\n    for valor in @\n      salida.push(valor)\n    salida\n",
  "std/sort.pengu": "realm sort\n\n-- Ordenación y búsqueda genéricas.\n--\n-- Cualquier tipo con `operator <` sirve, incluidas las runes que declaran\n-- `operator <=>` (el compilador deriva `<`, `>` y `>=`).\n\ninvoke \"std/vector\"\n\n-- Ordena en el sitio con inserción: estable y suficiente para los\n-- tamaños habituales de un juego o de una herramienta de consola.\ninsertion_sort = <T>( mut items: ref<vector<T>>) -> void\n  mut actual = size_t:: from (1)\n  while actual < #items\n    mut posicion = actual\n    while posicion > size_t:: from (0) and items[posicion] < items[posicion - size_t:: from (1)]\n      mut temporal: T = items[posicion]\n      items[posicion] = items[posicion - size_t:: from (1)]\n      items[posicion - size_t:: from (1)] = temporal\n      posicion -= size_t:: from (1)\n    actual += size_t:: from (1)\n\n    -- ¿Está ordenada de menor a mayor?\nis_sorted = <T>(items: ref<vector<T>>) -> bool\n  mut indice = size_t:: from (1)\n  while indice < #items\n    if items[indice] < items[indice - size_t:: from (1)]\n      return false\n    indice += size_t:: from (1)\n  true\n\n  -- Búsqueda binaria sobre una secuencia ya ordenada.\nbinary_search_sorted = <T>(items: ref<vector<T>>, buscado: T) -> size_t?\n  mut bajo = size_t:: from (0)\n  mut alto = #items\n  while bajo < alto\n    mut medio = (bajo + alto) / size_t:: from (2)\n    if items[medio] < buscado\n      bajo = medio + size_t:: from (1)\n    else\n      if buscado < items[medio]\n        alto = medio\n      else\n        return medio\n  none\n\n  -- Copia ordenada: no toca el original.\nsorted_copy = <T>(items: ref<vector<T>>) -> vector<T>\n  mut copia: vector<T> = []\n  for item in items\n    copia.push(item)\n  insertion_sort<T>( mut ref(copia))\n  copia\n",
  "std/string.pengu": "realm string\n\ninvoke \"std/char\"\ninvoke \"std/vector\"\n\n-- Intrínsecos: lo que solo C++ puede hacer de forma eficiente.\ndeclare\n  find_raw = (texto: ref<string>, buscado: ref<string>) -> size_t\n  rfind_raw = (texto: ref<string>, buscado: ref<string>) -> size_t\n  find_from_raw = (texto: ref<string>, buscado: ref<string>, desde: size_t) -> size_t\n  trim_raw = (texto: ref<string>) -> string\n  to_upper_raw = (texto: ref<string>) -> string\n  to_lower_raw = (texto: ref<string>) -> string\n  split_raw = (texto: ref<string>, separador: ref<string>) -> vector<string>\n  split_whitespace_raw = (texto: ref<string>) -> vector<string>\n  replace_first_raw = (texto: ref<string>, viejo: ref<string>, nuevo: ref<string>) -> string\n  reverse_raw = (texto: ref<string>) -> string\n  char_count_raw = (texto: ref<string>) -> size_t\n  parse_int_raw = (texto: ref<string>) -> int?\n  parse_double_raw = (texto: ref<string>) -> double?\n  bytes_raw = (texto: ref<string>) -> vector<uint8_t>\n\nenchanting string\n  compare = (otro: string) -> int\n    if @ < otro\n      -1\n    else if @ > otro\n      1\n    else\n      0\n\n  to_upper = -> string\n    to_upper_raw(ref(@))\n\n  to_lower = -> string\n    to_lower_raw(ref(@))\n\n  compare_ignore_case = (otro: string) -> int\n    izquierda = @.to_lower()\n    derecha = otro.to_lower()\n    izquierda.compare(derecha)\n\n  is_empty = -> bool\n    #@ == 0\n\n  starts_with = (prefijo: string) -> bool\n    largo = #@\n    if #prefijo > largo then false else @.substr(0, #prefijo) == prefijo\n\n  ends_with = (sufijo: string) -> bool\n    largo = #@\n    if #sufijo > largo then false else @.substr(largo - #sufijo, #sufijo) == sufijo\n\n  contains = (buscado: string) -> bool\n    buscado in @\n\n  find = (buscado: string) -> size_t?\n    pos = find_raw(ref(@), ref(buscado))\n    if pos == #@ then none else pos\n\n  rfind = (buscado: string) -> size_t?\n    pos = rfind_raw(ref(@), ref(buscado))\n    if pos == #@ then none else pos\n\n  find_from = (buscado: string, desde: size_t) -> size_t?\n    pos = find_from_raw(ref(@), ref(buscado), desde)\n    if pos == #@ then none else pos\n\n  count = (buscado: string) -> size_t\n    if #buscado == 0\n      return 0\n    mut total: size_t = 0\n    mut desde: size_t = 0\n    mut pos = find_from_raw(ref(@), ref(buscado), desde)\n    while pos < #@\n      total += 1\n      desde = pos + #buscado\n      pos = find_from_raw(ref(@), ref(buscado), desde)\n    total\n\n  trim = -> string\n    trim_raw(ref(@))\n\n  trim_start = -> string\n    mut i: size_t = 0\n    while i < #@ and @[i].is_space()\n      i += 1\n    @.substr(i, #@ - i)\n\n  trim_end = -> string\n    mut fin: size_t = #@\n    while fin > 0 and @[fin - 1].is_space()\n      fin -= 1\n    @.substr(0, fin)\n\n  trim_start_matches = (c: char) -> string\n    mut i: size_t = 0\n    while i < #@ and @[i] == c\n      i += 1\n    @.substr(i, #@ - i)\n\n  trim_end_matches = (c: char) -> string\n    mut fin: size_t = #@\n    while fin > 0 and @[fin - 1] == c\n      fin -= 1\n    @.substr(0, fin)\n\n  trim_matches = (c: char) -> string\n    @.trim_start_matches(c).trim_end_matches(c)\n\n  capitalize = -> string\n    if #@ == 0\n      return @\n    @.substr(0, 1).to_upper() + @.substr(1, #@ - 1).to_lower()\n\n  decapitalize = -> string\n    if #@ == 0\n      return @\n    @.substr(0, 1).to_lower() + @.substr(1, #@ - 1)\n\n  title_case = -> string\n    mut salida = \"\"\n    mut al_inicio = true\n    for i in 0..<#@\n      c = @[i]\n      if c.is_space()\n        salida += \"#{c}\"\n        al_inicio = true\n      else if al_inicio\n        salida += \"#{c.to_upper()}\"\n        al_inicio = false\n      else\n        salida += \"#{c.to_lower()}\"\n    salida\n\n  replace = (viejo: string, nuevo: string) -> string\n    if #viejo == 0\n      return @\n    mut salida = \"\"\n    mut desde: size_t = 0\n    mut pos = find_from_raw(ref(@), ref(viejo), desde)\n    while pos < #@\n      salida += @.substr(desde, pos - desde)\n      salida += nuevo\n      desde = pos + #viejo\n      pos = find_from_raw(ref(@), ref(viejo), desde)\n    salida += @.substr(desde, #@ - desde)\n    salida\n\n  replace_first = (viejo: string, nuevo: string) -> string\n    replace_first_raw(ref(@), ref(viejo), ref(nuevo))\n\n  remove_prefix = (prefijo: string) -> string\n    if @.starts_with(prefijo) then @.substr(#prefijo, #@ - #prefijo) else @\n\n  remove_suffix = (sufijo: string) -> string\n    if @.ends_with(sufijo) then @.substr(0, #@ - #sufijo) else @\n\n  split = (separador: string) -> vector<string>\n    split_raw(ref(@), ref(separador))\n\n  split_whitespace = -> vector<string>\n    split_whitespace_raw(ref(@))\n\n  split_lines = -> vector<string>\n    @.replace(\"\\r\\n\", \"\\n\").split(\"\\n\")\n\n  chars = -> vector<char>\n    mut salida: vector<char> = []\n    for i in 0..<#@\n      salida.push(@[i])\n    salida\n\n  bytes = -> vector<uint8_t>\n    bytes_raw(ref(@))\n\n  char_count = -> size_t\n    char_count_raw(ref(@))\n\n  get = (i: size_t) -> char?\n    if i < #@ then @[i] else none\n\n  mut pop = -> char?\n    if #@ == 0\n      none\n    else\n      ultimo = @[#@ - 1]\n      @ = @.substr(0, #@ - 1)\n      ultimo\n\n  repeat = (veces: int) -> string\n    mut salida = \"\"\n    for _ in 0..<veces\n      salida += @\n    salida\n\n  pad_start_with = (ancho: size_t, relleno: char) -> string\n    if #@ >= ancho\n      return @\n    mut salida = \"\"\n    for _ in 0..<(ancho - #@)\n      salida += \"#{relleno}\"\n    salida + @\n\n  pad_start = (ancho: size_t) -> string\n    @.pad_start_with(ancho, ' ')\n\n  pad_end_with = (ancho: size_t, relleno: char) -> string\n    if #@ >= ancho\n      return @\n    mut salida = @\n    for _ in 0..<(ancho - #@)\n      salida += \"#{relleno}\"\n    salida\n\n  pad_end = (ancho: size_t) -> string\n    @.pad_end_with(ancho, ' ')\n\n  pad_center_with = (ancho: size_t, relleno: char) -> string\n    if #@ >= ancho\n      return @\n    total = ancho - #@\n    izquierda = total / 2\n    derecha = total - izquierda\n    mut salida = \"\"\n    for _ in 0..<izquierda\n      salida += \"#{relleno}\"\n    salida += @\n    for _ in 0..<derecha\n      salida += \"#{relleno}\"\n    salida\n\n  pad_center = (ancho: size_t) -> string\n    @.pad_center_with(ancho, ' ')\n\n  reverse = -> string\n    reverse_raw(ref(@))\n\n  insert_at = (i: size_t, texto: string) -> string\n    if i >= #@\n      return @ + texto\n    @.substr(0, i) + texto + @.substr(i, #@ - i)\n\n  remove_range = (inicio: size_t, largo: size_t) -> string\n    if inicio >= #@\n      return @\n    mut fin = inicio + largo\n    if fin > #@\n      fin = #@\n    @.substr(0, inicio) + @.substr(fin, #@ - fin)\n\n  truncate = (largo: size_t) -> string\n    if #@ <= largo then @ else @.substr(0, largo)\n\n  substring = (inicio: size_t, fin: size_t) -> string\n    if inicio >= #@\n      return \"\"\n    mut limite = fin\n    if limite > #@\n      limite = #@\n    if limite <= inicio\n      return \"\"\n    @.substr(inicio, limite - inicio)\n\n  is_ascii = -> bool\n    for i in 0..<#@\n      if not @[i].is_ascii()\n        return false\n    true\n\n  is_alphabetic = -> bool\n    if #@ == 0\n      return false\n    for i in 0..<#@\n      if not @[i].is_alpha()\n        return false\n    true\n\n  is_numeric = -> bool\n    if #@ == 0\n      return false\n    for i in 0..<#@\n      if not @[i].is_digit()\n        return false\n    true\n\n  is_alphanumeric = -> bool\n    if #@ == 0\n      return false\n    for i in 0..<#@\n      if not @[i].is_alphanumeric()\n        return false\n    true\n\n  is_whitespace = -> bool\n    if #@ == 0\n      return false\n    for i in 0..<#@\n      if not @[i].is_space()\n        return false\n    true\n\n  is_upper = -> bool\n    if #@ == 0\n      return false\n    mut tiene_letra = false\n    for i in 0..<#@\n      c = @[i]\n      if c.is_lower()\n        return false\n      if c.is_upper()\n        tiene_letra = true\n    tiene_letra\n\n  is_lower = -> bool\n    if #@ == 0\n      return false\n    mut tiene_letra = false\n    for i in 0..<#@\n      c = @[i]\n      if c.is_upper()\n        return false\n      if c.is_lower()\n        tiene_letra = true\n    tiene_letra\n\n  to_int = -> int?\n    parse_int_raw(ref(@))\n\n  to_double = -> double?\n    parse_double_raw(ref(@))\n\n  to_bool = -> bool?\n    if @ == \"true\"\n      return true\n    if @ == \"false\"\n      return false\n    none\n\n  escape = -> string\n    barra = '\\\\'\n    mut salida = \"\"\n    for i in 0..<#@\n      c = @[i]\n      if c == '\\n'\n        salida += \"#{barra}n\"\n      else if c == '\\t'\n        salida += \"#{barra}t\"\n      else if c == '\\r'\n        salida += \"#{barra}r\"\n      else if c == barra\n        salida += \"#{barra}#{barra}\"\n      else\n        salida += \"#{c}\"\n    salida\n\n  unescape = -> string\n    barra = '\\\\'\n    mut salida = \"\"\n    mut i: size_t = 0\n    while i < #@\n      c = @[i]\n      if c == barra and i + 1 < #@\n        siguiente = @[i + 1]\n        if siguiente == 'n'\n          salida += \"\\n\"\n        else if siguiente == 't'\n          salida += \"\\t\"\n        else if siguiente == 'r'\n          salida += \"\\r\"\n        else\n          salida += \"#{siguiente}\"\n        i += 2\n      else\n        salida += \"#{c}\"\n        i += 1\n    salida\n",
  "std/test.pengu": "realm test\n\n-- Aserciones para pruebas escritas en PenguScript.\n--\n-- Todas panican con un mensaje cuando la comprobación falla, así que un\n-- programa de pruebas termina con código distinto de cero.\n\ninvoke \"std/assert\"\n\n-- La condición es verdadera.\nis_true = (valor: bool, mensaje: string = \"se esperaba true\") -> void\n  if not valor\n    assert::fail(mensaje)\n\n    -- La condición es falsa.\nis_false = (valor: bool, mensaje: string = \"se esperaba false\") -> void\n  if valor\n    assert::fail(mensaje)\n\n    -- Dos valores son iguales.\nequal = <T>(actual: T, esperado: T, mensaje: string = \"los valores no coinciden\") -> void\n  if not (actual == esperado)\n    assert::fail(mensaje)\n\n    -- Dos valores son distintos.\nnot_equal = <T>(actual: T, esperado: T, mensaje: string = \"los valores coinciden\") -> void\n  if actual == esperado\n    assert::fail(mensaje)\n\n    -- El opcional tiene valor.\nis_some = <T>(valor: T?, mensaje: string = \"se esperaba un valor\") -> void\n  if not valor.is_some()\n    assert::fail(mensaje)\n\n    -- El opcional está vacío.\nis_none = <T>(valor: T?, mensaje: string = \"se esperaba none\") -> void\n  if valor.is_some()\n    assert::fail(mensaje)\n",
  "std/time.pengu": "realm time\n\ninvoke \"std/format\"\ninvoke \"std/int\"\ninvoke \"std/integers\"\ninvoke \"std/string\"\ninvoke \"std/vector\"\n\ndeclare\n  now_millis = -> int64_t\n  now_nanos = -> int64_t\n  now_seconds = -> int64_t\n  monotonic_millis = -> int64_t\n  monotonic_nanos = -> int64_t\n  sleep_millis = (millis: int64_t) -> void\n  parts = (millis: int64_t) -> vector<int>\n  format_datetime = (millis: int64_t) -> string\n\nrune Duration\n  millis: int64_t\n\n  constructor(millis: int64_t)\n    @millis = millis\n\nenchanting Duration\n  as_millis = -> int64_t\n    @millis\n\n  as_seconds = -> double\n    (@millis as double) / 1000.0\n\n  as_seconds_int = -> int64_t\n    @millis / 1000\n\n  as_minutes = -> double\n    (@millis as double) / 60000.0\n\n  is_zero = -> bool\n    @millis == 0\n\n  is_negative = -> bool\n    @millis < 0\n\n  abs = -> Duration\n    Duration(@millis.abs())\n\n  scaled = (factor: double) -> Duration\n    Duration(int64_t::try_from((@millis as double) * factor).value_or(0))\n\n  add = (otra: Duration) -> Duration\n    Duration(@millis + otra.as_millis())\n\n  sub = (otra: Duration) -> Duration\n    Duration(@millis - otra.as_millis())\n\n  to_string = -> string\n    if @millis.abs() >= 1000\n      \"#{format::fixed(@millis as double / 1000.0, 3)}s\"\n    else\n      \"#{@millis}ms\"\n\n  operator + = (otra: Duration) -> Duration\n    Duration(@millis + otra.as_millis())\n\n  operator - = (otra: Duration) -> Duration\n    Duration(@millis - otra.as_millis())\n\n  operator * = (factor: int64_t) -> Duration\n    Duration(@millis * factor)\n\n  operator <=> = (otra: Duration) -> Ordering\n    @millis <=> otra.as_millis()\n\n  operator == = (otra: Duration) -> bool\n    @millis == otra.as_millis()\n\nrune DateTime\n  millis: int64_t\n  year: int\n  month: int\n  day: int\n  hour: int\n  minute: int\n  second: int\n\n  constructor(millis: int64_t, year: int, month: int, day: int, hour: int, minute: int, second: int)\n    @millis = millis\n    @year = year\n    @month = month\n    @day = day\n    @hour = hour\n    @minute = minute\n    @second = second\n\nenchanting DateTime\n  to_string = -> string\n    format_datetime(@millis)\n\n  as_millis = -> int64_t\n    @millis\n\ndatetime_from_millis = (millis: int64_t) -> DateTime\n  partes = parts(millis)\n  DateTime(millis, partes[0], partes[1], partes[2], partes[3], partes[4], partes[5])\n\ndatetime_now = -> DateTime\n  datetime_from_millis(now_millis())\n\nrune Instant\n  millis: int64_t\n\n  constructor(millis: int64_t)\n    @millis = millis\n\nenchanting Instant\n  as_millis = -> int64_t\n    @millis\n\n  as_seconds = -> double\n    (@millis as double) / 1000.0\n\n  add = (duracion: Duration) -> Instant\n    Instant(@millis + duracion.as_millis())\n\n  sub = (duracion: Duration) -> Instant\n    Instant(@millis - duracion.as_millis())\n\n  elapsed = -> Duration\n    Duration(now_millis() - @millis)\n\n  until = (otro: Instant) -> Duration\n    Duration(otro.as_millis() - @millis)\n\n  to_string = -> string\n    format_datetime(@millis)\n\n  to_datetime = -> DateTime\n    partes = parts(@millis)\n    DateTime(@millis, partes[0], partes[1], partes[2], partes[3], partes[4], partes[5])\n\n  operator - = (otro: Instant) -> Duration\n    Duration(@millis - otro.as_millis())\n\n  operator <=> = (otro: Instant) -> Ordering\n    @millis <=> otro.as_millis()\n\nduration_from_millis = (millis: int64_t) -> Duration\n  Duration(millis)\n\nduration_from_seconds = (segundos: int64_t) -> Duration\n  Duration(segundos * 1000)\n\nduration_from_double_seconds = (segundos: double) -> Duration\n  Duration(int64_t::try_from(segundos * 1000.0).value_or(0))\n\nduration_from_minutes = (minutos: int64_t) -> Duration\n  Duration(minutos * 60000)\n\nduration_from_hours = (horas: int64_t) -> Duration\n  Duration(horas * 3600000)\n\nduration_from_days = (dias: int64_t) -> Duration\n  Duration(dias * 86400000)\n\nduration_zero = -> Duration\n  Duration(0)\n\ninstant_now = -> Instant\n  Instant(now_millis())\n\ninstant_from_millis = (millis: int64_t) -> Instant\n  Instant(millis)\n",
  "std/tuple.pengu": "realm tuple\n\nenchanting tuple<A, B>\n  len = -> size_t\n    2\n\n  swap = -> tuple<B, A>\n    a, b = @\n    (b, a)\n\n  to_pair = -> pair<A, B>\n    (@.first, @.second)\n\nenchanting tuple<A, B, C>\n  len = -> size_t\n    3\n\n  first = -> A\n    a, b, c = @\n    a\n\n  second = -> B\n    a, b, c = @\n    b\n\n  third = -> C\n    a, b, c = @\n    c\n",
  "std/vector.pengu": "realm vector\n\ninvoke \"std/pair\"\n\nenchanting vector<T>\n  is_empty = -> bool\n    #@ == 0\n\n  first = -> T?\n    if #@ == 0 then none else @[0]\n\n  last = -> T?\n    if #@ == 0 then none else @[#@ - 1]\n\n  index_of = (buscado: T) -> size_t?\n    mut i: size_t = 0\n    mut encontrado: size_t? = none\n    while i < #@\n      if @[i] == buscado\n        encontrado = i\n        break\n      i += 1\n    encontrado\n\n  contains = (buscado: T) -> bool\n    mut i: size_t = 0\n    mut esta = false\n    while i < #@\n      if @[i] == buscado\n        esta = true\n        break\n      i += 1\n    esta\n\n  join = (separador: string) -> string\n    mut salida = \"\"\n    mut i: size_t = 0\n    while i < #@\n      if i > 0\n        salida += separador\n      salida += \"#{@[i]}\"\n      i += 1\n    salida\n\n  mut reverse = -> void\n    if #@ == 0\n      return\n    mut i: size_t = 0\n    mut j: size_t = #@ - 1\n    while i < j\n      temporal = @[i]\n      @[i] = @[j]\n      @[j] = temporal\n      i += 1\n      j -= 1\n\n  mut sort = -> void\n    mut i = 1\n    while i < #@\n      mut j: size_t = i\n      while j > 0 and @[j - 1] > @[j]\n        temporal = @[j]\n        @[j] = @[j - 1]\n        @[j - 1] = temporal\n        j -= 1\n      i += 1\n\n  get_or = (indice: size_t, alternativa: T) -> T\n    if indice < #@ then @[indice] else alternativa\n\n  first_or = (alternativa: T) -> T\n    if #@ == 0 then alternativa else @[0]\n\n  last_or = (alternativa: T) -> T\n    if #@ == 0 then alternativa else @[#@ - 1]\n\n  mut remove = (valor: T) -> bool\n    indice = @.index_of(valor)\n    if indice.is_some()\n      @.remove_at(indice.value())\n      true\n    else\n      false\n\n  mut remove_all = (valor: T) -> size_t\n    mut borrados: size_t = 0\n    mut indice = @.index_of(valor)\n    while indice.is_some()\n      @.remove_at(indice.value())\n      borrados += 1\n      indice = @.index_of(valor)\n    borrados\n\n  mut extend = (otro: ref<vector<T>>) -> void\n    for valor in otro\n      @.push(valor)\n\n  mut retain = (predicado: function<(T) -> bool>) -> void\n    mut conservados: vector<T> = []\n    for valor in @\n      if predicado(valor)\n        conservados.push(valor)\n    @ = conservados\n\n  mut fill = (valor: T) -> void\n    mut i: size_t = 0\n    while i < #@\n      @[i] = valor\n      i += 1\n\n  mut swap = (i: size_t, j: size_t) -> void\n    temporal = @[i]\n    @[i] = @[j]\n    @[j] = temporal\n\n  mut rotate_left = (n: size_t) -> void\n    if #@ == 0\n      return\n    mut pasos = n % #@\n    while pasos > 0\n      primero = @[0]\n      mut i: size_t = 0\n      while i + 1 < #@\n        @[i] = @[i + 1]\n        i += 1\n      @[#@ - 1] = primero\n      pasos -= 1\n\n  mut rotate_right = (n: size_t) -> void\n    if #@ == 0\n      return\n    mut pasos = n % #@\n    while pasos > 0\n      ultimo = @[#@ - 1]\n      mut i = #@ - 1\n      while i > 0\n        @[i] = @[i - 1]\n        i -= 1\n      @[0] = ultimo\n      pasos -= 1\n\n  any = (predicado: function<(T) -> bool>) -> bool\n    for valor in @\n      if predicado(valor)\n        return true\n    false\n\n  all = (predicado: function<(T) -> bool>) -> bool\n    for valor in @\n      if not predicado(valor)\n        return false\n    true\n\n  none = (predicado: function<(T) -> bool>) -> bool\n    for valor in @\n      if predicado(valor)\n        return false\n    true\n\n  count_if = (predicado: function<(T) -> bool>) -> size_t\n    mut total: size_t = 0\n    for valor in @\n      if predicado(valor)\n        total += 1\n    total\n\n  find_if = (predicado: function<(T) -> bool>) -> T?\n    for valor in @\n      if predicado(valor)\n        return valor\n    none\n\n  position_if = (predicado: function<(T) -> bool>) -> size_t?\n    mut i: size_t = 0\n    while i < #@\n      if predicado(@[i])\n        return i\n      i += 1\n    none\n\n  fold = (combinar: function<(T, T) -> T>, inicial: T) -> T\n    mut acumulado = inicial\n    for valor in @\n      acumulado = combinar(acumulado, valor)\n    acumulado\n\n  map = (transformar: function<(T) -> T>) -> vector<T>\n    mut salida: vector<T> = []\n    for valor in @\n      salida.push(transformar(valor))\n    salida\n\n  filter = (predicado: function<(T) -> bool>) -> vector<T>\n    mut salida: vector<T> = []\n    for valor in @\n      if predicado(valor)\n        salida.push(valor)\n    salida\n\n  mut transform = (transformar: function<(T) -> T>) -> void\n    mut i: size_t = 0\n    while i < #@\n      @[i] = transformar(@[i])\n      i += 1\n\n  min = -> T?\n    if #@ == 0\n      return none\n    mut candidato = @[0]\n    for valor in @\n      if candidato > valor\n        candidato = valor\n    candidato\n\n  max = -> T?\n    if #@ == 0\n      return none\n    mut candidato = @[0]\n    for valor in @\n      if candidato < valor\n        candidato = valor\n    candidato\n\n  is_sorted = -> bool\n    mut i: size_t = 1\n    while i < #@\n      if @[i - 1] > @[i]\n        return false\n      i += 1\n    true\n\n  mut sort_by = (comparar: function<(T, T) -> int>) -> void\n    mut i: size_t = 1\n    while i < #@\n      mut j = i\n      while j > 0 and comparar(@[j - 1], @[j]) > 0\n        temporal = @[j]\n        @[j] = @[j - 1]\n        @[j - 1] = temporal\n        j -= 1\n      i += 1\n\n  sorted = -> vector<T>\n    mut copia: vector<T> = []\n    for valor in @\n      copia.push(valor)\n    copia.sort()\n    copia\n\n  sorted_by = (comparar: function<(T, T) -> int>) -> vector<T>\n    mut copia: vector<T> = []\n    for valor in @\n      copia.push(valor)\n    copia.sort_by(comparar)\n    copia\n\n  mut dedup = -> void\n    mut sin_repetidos: vector<T> = []\n    for valor in @\n      if #sin_repetidos == 0\n        sin_repetidos.push(valor)\n      else if not (sin_repetidos[#sin_repetidos - 1] == valor)\n        sin_repetidos.push(valor)\n    @ = sin_repetidos\n\n  binary_search = (valor: T) -> size_t?\n    mut inicio: size_t = 0\n    mut fin: size_t = #@\n    while inicio < fin\n      medio = inicio + (fin - inicio) / 2\n      if @[medio] < valor\n        inicio = medio + 1\n      else\n        fin = medio\n    if inicio < #@ and @[inicio] == valor\n      return inicio\n    none\n\n  take = (n: size_t) -> vector<T>\n    mut salida: vector<T> = []\n    mut i: size_t = 0\n    while i < n and i < #@\n      salida.push(@[i])\n      i += 1\n    salida\n\n  skip = (n: size_t) -> vector<T>\n    mut salida: vector<T> = []\n    mut i = n\n    while i < #@\n      salida.push(@[i])\n      i += 1\n    salida\n\n  slice = (inicio: size_t, largo: size_t) -> vector<T>\n    mut salida: vector<T> = []\n    mut i = inicio\n    while i < #@ and i < inicio + largo\n      salida.push(@[i])\n      i += 1\n    salida\n\n  chunks = (tamano: size_t) -> vector<vector<T>>\n    mut salida: vector<vector<T>> = []\n    if tamano == 0\n      return salida\n    mut actual: vector<T> = []\n    for valor in @\n      actual.push(valor)\n      if #actual == tamano\n        salida.push(actual)\n        actual = []\n    if #actual > 0\n      salida.push(actual)\n    salida\n\n  windows = (tamano: size_t) -> vector<vector<T>>\n    mut salida: vector<vector<T>> = []\n    if tamano == 0 or tamano > #@\n      return salida\n    mut i: size_t = 0\n    while i + tamano <= #@\n      mut ventana: vector<T> = []\n      mut j: size_t = 0\n      while j < tamano\n        ventana.push(@[i + j])\n        j += 1\n      salida.push(ventana)\n      i += 1\n    salida\n\n  enumerate = -> vector<pair<size_t, T>>\n    mut salida: vector<pair<size_t, T>> = []\n    mut i: size_t = 0\n    while i < #@\n      mut par: pair<size_t, T> = (i, @[i])\n      salida.push(par)\n      i += 1\n    salida\n",
};
